import { createRoute, z } from '@hono/zod-openapi'

const IgnoredParametersUnsupportedSchema = z
  .array(z.string())
  .openapi({
    description:
      'An array of any parameters sent in the request that are not\nsupported by the endpoint.\n\nSee [error handling](/api/rest-error-handling#ignored-parameters) documentation\nfor details on this and its change history.\n',
  })
  .openapi('IgnoredParametersUnsupported')

const EventIdSchemaSchema = z
  .int()
  .openapi({
    description:
      'The ID of the event. Events appear in increasing order but may not be consecutive.\n',
  })
  .openapi('EventIdSchema')

const EventTypeSchemaSchema = z
  .string()
  .openapi({
    description:
      "The event's type, relevant both for client-side dispatch and server-side\nfiltering by event type in [POST /register](/api/register-queue).\n",
  })
  .openapi('EventTypeSchema')

const AnchorSchema = z.string().openapi('Anchor')

const AttachmentSchema = z
  .strictObject({
    id: z.int().exactOptional().openapi({ description: 'The unique ID for the attachment.\n' }),
    name: z.string().exactOptional().openapi({ description: 'Name of the uploaded file.\n' }),
    path_id: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'A representation of the path of the file within the\nrepository of user-uploaded files. If the `path_id` of a\nfile is `{realm_id}/ab/cdef/temp_file.py`, its URL will be:\n`{server_url}/user_uploads/{realm_id}/ab/cdef/temp_file.py`.\n',
      }),
    size: z.int().exactOptional().openapi({ description: 'Size of the file in bytes.\n' }),
    create_time: z
      .int()
      .exactOptional()
      .openapi({
        description:
          'Time when the attachment was uploaded as a UNIX timestamp.\n\n**Changes**: Before Zulip 12.0 (feature level 443), this value\nwas milliseconds since the epoch, not seconds.\n\nChanged in Zulip 3.0 (feature level 22). This field was\npreviously a floating point number.\n',
      }),
    message_ids: z
      .array(z.int())
      .exactOptional()
      .openapi({
        description:
          'Array containing the IDs of messages that reference this\n[uploaded file](/api/upload-file). This includes messages\nsent by any user in the Zulip organization who sent a\nmessage containing a link to the uploaded file.\n\n**Changes**: In Zulip 12.0 (feature level 472), this\nreplaced the previous `messages` field, which was an array\nof objects containing both `id` and `date_sent` properties.\n',
      }),
  })
  .openapi({
    description: 'Dictionary containing details of a file uploaded by a user.\n',
    required: [],
  })
  .openapi('Attachment')

const DefaultPushNotificationsSchema = z
  .boolean()
  .openapi({
    description:
      "Whether mobile push notifications will be enabled by default when a\nuser first subscribes to this channel, potentially overriding the\nuser's [default mobile notification\nsetting](/help/channel-notifications#configure-default-notifications-for-all-channels)\nfor channel messages.\n\nBecause this default is applied only the first time a user\nsubscribes, unsubscribing and resubscribing a user does not reset\ntheir preference to this channel default.\n\nOnly organization administrators can set or modify this value.\n\n**Changes**: New in Zulip 13.0 (feature level 507).\n",
    example: true,
  })
  .openapi('DefaultPushNotifications')

const TopicsPolicySchema = z
  .enum(['inherit', 'allow_empty_topic', 'disable_empty_topic', 'empty_topic_only'])
  .openapi({
    example: 'inherit',
    description:
      'Whether [named topics](/help/introduction-to-topics) and the empty\ntopic (i.e., ["general chat" topic](/help/general-chat-topic))\nare enabled in this channel.\n\n- `"inherit"`: Messages can be sent to named topics in this channel,\n  and the [organization-level `realm_topics_policy`][realm-topics-policy]\n  is used for whether messages can be sent to the empty topic in this\n  channel.\n- `"allow_empty_topic"`: Messages can be sent to both named topics and\n  the empty topic in this channel.\n- `"disable_empty_topic"`: Messages can be sent to named topics in this\n  channel, but the empty topic is disabled.\n- `"empty_topic_only"`: Messages can be sent to the empty topic in this\n  channel, but named topics are disabled. See ["general chat"\n  channels](/help/general-chat-channels).\n\nThe `"empty_topic_only"` policy can only be set if all existing messages\nin the channel are already in the empty topic.\n\nWhen creating a new channel, if the `topics_policy` is not specified, the\n`"inherit"` option will be set.\n\n**Changes**: In Zulip 11.0 (feature level 404), the `"empty_topic_only"`\noption was added.\n\nNew in Zulip 11.0 (feature level 392).\n\n[realm-topics-policy]: /help/require-topics#set-the-default-general-chat-topic-configuration\n',
  })
  .openapi('TopicsPolicy')

const FolderIdSchema = z
  .int()
  .nullable()
  .openapi({
    description:
      'The ID of the folder to which the channel belongs.\n\nIs `null` if channel does not belong to any folder.\n\n**Changes**: New in Zulip 11.0 (feature level 389).\n',
  })
  .openapi('FolderId')

const GroupSettingValueSchema = z
  .xor([
    z
      .int()
      .openapi({
        description: 'The ID of the [user group](/help/user-groups) with this permission.\n',
      }),
    z
      .strictObject({
        direct_members: z
          .array(z.int())
          .exactOptional()
          .openapi({
            description:
              'The list of IDs of individual users in the collection of users with this permission.\n\n**Changes**: Prior to Zulip 10.0 (feature level 303), this list would include\ndeactivated users who had the permission before being deactivated.\n',
          }),
        direct_subgroups: z
          .array(z.int())
          .exactOptional()
          .openapi({
            description:
              'The list of IDs of the groups in the collection of users with this permission.\n',
          }),
      })
      .openapi({ description: 'An object with these fields:\n', required: [] }),
  ])
  .openapi('GroupSettingValue')

const ChannelCanAddSubscribersGroupSchema = GroupSettingValueSchema.and(
  z
    .any()
    .openapi({
      description:
        'A [group-setting value][setting-values] defining the set of users\nwho have permission to add subscribers to this channel.\n\nUsers who can administer the channel or have similar realm-level\npermissions can add subscribers to a public channel regardless\nof the value of this setting.\n\nUsers in this group need not be subscribed to a private channel to\nadd subscribers to it.\n\nNote that a user must [have content access](/help/channel-permissions)\nto a channel and permission to administer the channel in order to\nmodify this setting.\n\n**Changes**: New in Zulip 10.0 (feature level 342). Previously, there was no\nchannel-level setting for this permission.\n\n[setting-values]: /api/group-setting-values\n',
    }),
).openapi('ChannelCanAddSubscribersGroup')

const CanRemoveSubscribersGroupSchema = GroupSettingValueSchema.and(
  z
    .any()
    .openapi({
      description:
        'A [group-setting value][setting-values] defining the set of users\nwho have permission to remove subscribers from this channel.\n\nOrganization administrators can unsubscribe others from a channel as though\nthey were in this group without being explicitly listed here.\n\nNote that a user must have metadata access to a channel and permission\nto administer the channel in order to modify this setting.\n\n**Changes**: Prior to Zulip 10.0 (feature level 349), channel administrators\ncould not unsubscribe other users if they were not an organization\nadministrator or part of `can_remove_subscribers_group`. Realm administrators\nwere not allowed to unsubscribe other users from a private channel if they\nwere not subscribed to that channel.\n\nPrior to Zulip 10.0 (feature level 320), this value was always the integer\nID of a system group.\n\nBefore Zulip 8.0 (feature level 197), the `can_remove_subscribers_group`\nsetting was named `can_remove_subscribers_group_id`.\n\nNew in Zulip 6.0 (feature level 142).\n\n[setting-values]: /api/group-setting-values\n',
    }),
).openapi('CanRemoveSubscribersGroup')

const CanAdministerChannelGroupSchema = GroupSettingValueSchema.and(
  z
    .any()
    .openapi({
      description:
        'A [group-setting value][setting-values] defining the set of users\nwho have permission to administer this channel.\n\nOrganization administrators can administer every channel as though they were\nin this group without being explicitly listed here.\n\nNote that a user must have metadata access to a channel and permission\nto administer the channel in order to modify this setting.\n\n**Changes**: Prior to Zulip 10.0 (feature level 349) a user needed to\n[have content access](/help/channel-permissions) to a channel in\norder to modify it. The exception to this rule was that organization\nadministrators can edit channel names and descriptions without\nhaving full access to the channel.\n\nNew in Zulip 10.0 (feature level 325). Prior to this\nchange, the permission to administer channels was limited to realm\nadministrators.\n\n[setting-values]: /api/group-setting-values\n',
    }),
).openapi('CanAdministerChannelGroup')

const CanDeleteAnyMessageGroupSchema = GroupSettingValueSchema.and(
  z
    .any()
    .openapi({
      description:
        'A [group-setting value][setting-values] defining the set of users\nwho have permission to delete any message in the channel.\n\nNote that a user must [have content access](/help/channel-permissions) to a\nchannel in order to delete any message in the channel.\n\nUsers present in the organization-level `can_delete_any_message_group`\nsetting can always delete any message in the channel if they\n[have content access](/help/channel-permissions) to that channel.\n\n**Changes**: New in Zulip 11.0 (feature level 407). Prior to this\nchange, only the users in `can_delete_any_message_group` were able\ndelete any message in the organization.\n\n[setting-values]: /api/group-setting-values\n',
    }),
).openapi('CanDeleteAnyMessageGroup')

const CanDeleteOwnMessageGroupSchema = GroupSettingValueSchema.and(
  z
    .any()
    .openapi({
      description:
        'A [group-setting value][setting-values] defining the set of users\nwho have permission to delete the messages that they have sent in the channel.\n\n[update-group-setting]: /api/group-setting-values#updating-group-setting-values\n\nNote that a user must [have content access](/help/channel-permissions) to a\nchannel in order to delete their own message in the channel.\n\nUsers with permission to delete any message in the channel\nand users present in the organization-level `can_delete_own_message_group` setting\ncan always delete their own messages in the channel if they\n[have content access](/help/channel-permissions) to that channel.\n\n**Changes**: New in Zulip 11.0 (feature level 407). Prior to this\nchange, only the users in the organization-level `can_delete_any_message_group`\nand `can_delete_own_message_group` settings were able delete their own messages in\nthe organization.\n\n[setting-values]: /api/group-setting-values\n',
    }),
).openapi('CanDeleteOwnMessageGroup')

const CanMoveMessagesOutOfChannelGroupSchema = GroupSettingValueSchema.and(
  z
    .any()
    .openapi({
      description:
        'A [group-setting value][setting-values] defining the set of users\nwho have permission to move messages out of this channel.\n\nNote that a user must [have content access](/help/channel-permissions) to a\nchannel in order to move messages out of the channel.\n\nChannel administrators and users present in the organization-level\n`can_move_messages_between_channels_group` setting can always move messages\nout of the channel if they [have content access](/help/channel-permissions) to\nthe channel.\n\n**Changes**: New in Zulip 11.0 (feature level 396). Prior to this\nchange, only the users in `can_move_messages_between_channels_group` were able\nmove messages between channels.\n\n[setting-values]: /api/group-setting-values\n',
    }),
).openapi('CanMoveMessagesOutOfChannelGroup')

const CanMoveMessagesWithinChannelGroupSchema = GroupSettingValueSchema.and(
  z
    .any()
    .openapi({
      description:
        'A [group-setting value][setting-values] defining the set of users\nwho have permission to move messages within this channel.\n\nNote that a user must [have content access](/help/channel-permissions) to a\nchannel in order to move messages within the channel.\n\nChannel administrators and users present in the organization-level\n`can_move_messages_between_topics_group` setting can always move messages\nwithin the channel if they [have content access](/help/channel-permissions) to\nthe channel.\n\n**Changes**: New in Zulip 11.0 (feature level 396). Prior to this\nchange, only the users in `can_move_messages_between_topics_group` were able\nmove messages between topics of a channel.\n\n[setting-values]: /api/group-setting-values\n',
    }),
).openapi('CanMoveMessagesWithinChannelGroup')

const CanSendMessageGroupSchema = GroupSettingValueSchema.and(
  z
    .any()
    .openapi({
      description:
        'A [group-setting value][setting-values] defining the set of users\nwho have permission to post in this channel.\n\nNote that a user must have metadata access to a channel and permission\nto administer the channel in order to modify this setting.\n\nNote that using this permission to send a message to a new topic requires\nalso having permission to create new topics in the channel.\n\n**Changes**: New in Zulip 10.0 (feature level 333). Previously\n`stream_post_policy` field used to control the permission to\npost in the channel.\n\n[setting-values]: /api/group-setting-values\n',
    }),
).openapi('CanSendMessageGroup')

const CanSubscribeGroupSchema = GroupSettingValueSchema.and(
  z
    .any()
    .openapi({
      description:
        'A [group-setting value][setting-values] defining the set of users\nwho have permission to subscribe themselves to this channel.\n\nEveryone, excluding guests, can subscribe to any public channel\nirrespective of this setting.\n\nUsers in this group can subscribe to a private channel as well.\n\nNote that a user must [have content access](/help/channel-permissions)\nto a channel and permission to administer the channel in order to\nmodify this setting.\n\n**Changes**: New in Zulip 10.0 (feature level 357).\n\n[setting-values]: /api/group-setting-values\n',
    }),
).openapi('CanSubscribeGroup')

const CanResolveTopicsGroupSchema = GroupSettingValueSchema.and(
  z
    .any()
    .openapi({
      description:
        'A [group-setting value][setting-values] defining the set of users\nwho have permission to resolve topics in the channel.\n\nUsers who have similar realm-level permissions can resolve topics\nin a channel regardless of the value of this setting.\n\n**Changes**: New in Zulip 11.0 (feature level 402).\n\n[setting-values]: /api/group-setting-values\n',
    }),
).openapi('CanResolveTopicsGroup')

const CanCreateTopicGroupSchema = GroupSettingValueSchema.and(
  z
    .any()
    .openapi({
      description:
        'A [group-setting value][setting-values] defining the set of users\nwho have permission to create a new topic in this channel.\n\nNote that using this permission requires also having permission to\nsend messages in the channel.\n\nNote that this must be the `role:everyone` [system group][system-groups]\nfor [private channels with protected history][private-channels].\n\n**Changes**: New in Zulip 12.0 (feature level 441). Previously,\nif you could send messages in a channel, you could create topics in\nthe channel.\n\n[setting-values]: /api/group-setting-values\n[private-channels]: /help/channel-permissions/#private-channels\n[system-groups]: /api/group-setting-values#system-groups\n',
    }),
).openapi('CanCreateTopicGroup')

const BasicChannelBaseSchema = z
  .object({
    stream_id: z.int().exactOptional().openapi({ description: 'The unique ID of the channel.\n' }),
    name: z.string().exactOptional().openapi({ description: 'The name of the channel.\n' }),
    is_archived: z
      .boolean()
      .exactOptional()
      .openapi({
        description:
          'A boolean indicating whether the channel is [archived](/help/archive-a-channel).\n\n**Changes**: New in Zulip 10.0 (feature level 315).\nPreviously, this endpoint never returned archived channels.\n',
      }),
    description: z
      .string()
      .exactOptional()
      .openapi({
        description:
          "The short description of the channel in [Zulip-flavored Markdown](/help/format-your-message-using-markdown) format,\nintended to be used to prepopulate UI for editing a channel's\ndescription.\n\nSee [Markdown message formatting](/api/message-formatting) for details on Zulip's HTML format.\n",
      }),
    date_created: z
      .int()
      .exactOptional()
      .openapi({
        description:
          'The UNIX timestamp for when the channel was created, in UTC seconds.\n\n**Changes**: New in Zulip 4.0 (feature level 30).\n',
      }),
    creator_id: z
      .int()
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'The ID of the user who created this channel.\n\nA `null` value means the channel has no recorded creator, which is often\nbecause the channel is very old, was created during realm creation or\nbecause it was created via a data import tool or [management command][management-commands].\n\n**Changes**: New in Zulip 9.0 (feature level 254).\n\n[management-commands]: https://zulip.readthedocs.io/en/latest/production/management-commands.html\n',
      }),
    invite_only: z
      .boolean()
      .exactOptional()
      .openapi({
        description:
          'Specifies whether the channel is private or not.\nOnly people who have been invited can access a private channel.\n',
      }),
    rendered_description: z
      .string()
      .exactOptional()
      .openapi({
        description:
          'The short description of the channel rendered as HTML, intended to\nbe used when displaying the channel description in a UI.\n\nOne should use the standard Zulip rendered_markdown CSS when\ndisplaying this content so that emoji, LaTeX, and other syntax\nwork correctly. And any client-side security logic for\nuser-generated message content should be applied when displaying\nthis HTML as though it were the body of a Zulip message.\n',
      }),
    is_web_public: z
      .boolean()
      .exactOptional()
      .openapi({
        description:
          'Whether the channel has been configured to allow unauthenticated\naccess to its message history from the web.\n\n**Changes**: New in Zulip 2.1.0.\n',
      }),
    stream_post_policy: z
      .int()
      .exactOptional()
      .openapi({
        deprecated: true,
        description:
          'A deprecated representation of a superset of the users who\nhave permission to post messages to the channel available\nfor backwards-compatibility. Clients should use\n`can_send_message_group` instead.\n\nIt is an enum with the following possible values, corresponding\nto roles/system groups:\n\n- 1 = Any user can post.\n- 2 = Only administrators can post.\n- 3 = Only [full members][calc-full-member] can post.\n- 4 = Only moderators can post.\n\n**Changes**: Deprecated in Zulip 10.0 (feature level 333) and\nreplaced by `can_send_message_group`, which supports finer\nresolution of configurations, resulting in this property being\ninaccurate following that transition.\n\nNew in Zulip 3.0 (feature level 1), replacing the previous\n`is_announcement_only` boolean.\n\n[calc-full-member]: /api/roles-and-permissions#determining-if-a-user-is-a-full-member\n',
      }),
    message_retention_days: z
      .int()
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'Number of days that messages sent to this channel will be stored\nbefore being automatically deleted by the [message retention\npolicy](/help/message-retention-policy). There are two special values:\n\n- `null`, the default, means the channel will inherit the organization\n  level setting.\n- `-1` encodes retaining messages in this channel forever.\n\n**Changes**: New in Zulip 3.0 (feature level 17).\n',
      }),
    default_push_notifications: DefaultPushNotificationsSchema.exactOptional(),
    history_public_to_subscribers: z
      .boolean()
      .exactOptional()
      .openapi({
        description:
          'Whether the history of the channel is public to its subscribers.\n\nCurrently always true for public channels (i.e. `"invite_only": false` implies\n`"history_public_to_subscribers": true`), but clients should not make that\nassumption, as we may change that behavior in the future.\n',
      }),
    topics_policy: TopicsPolicySchema.exactOptional(),
    first_message_id: z
      .int()
      .nullable()
      .exactOptional()
      .openapi({
        description:
          'The ID of the first message in the channel.\n\nIntended to help clients determine whether they need to display\nUI like the "show all topics" widget that would suggest the channel\nhas older history that can be accessed.\n\nIs `null` for channels with no message history.\n\n**Changes**: New in Zulip 2.1.0.\n',
      }),
    folder_id: FolderIdSchema.exactOptional(),
    is_recently_active: z
      .boolean()
      .exactOptional()
      .openapi({
        description:
          'Whether the channel has recent message activity. Clients should use this to implement\n[hide inactive channels](/help/manage-inactive-channels) if\n`demote_inactive_streams` is enabled.\n\n**Changes**: New in Zulip 10.0 (feature level 323). Previously, clients implemented the\ndemote_inactive_streams from local message history, resulting in a choppy loading\nexperience.\n',
      }),
    is_announcement_only: z
      .boolean()
      .exactOptional()
      .openapi({
        deprecated: true,
        description:
          'Whether the given channel is announcement only or not.\n\n**Changes**: Deprecated in Zulip 3.0 (feature level 1). Clients\nshould use `stream_post_policy` instead.\n',
      }),
    can_add_subscribers_group: ChannelCanAddSubscribersGroupSchema.exactOptional(),
    can_remove_subscribers_group: CanRemoveSubscribersGroupSchema.exactOptional(),
    can_administer_channel_group: CanAdministerChannelGroupSchema.exactOptional(),
    can_delete_any_message_group: CanDeleteAnyMessageGroupSchema.exactOptional(),
    can_delete_own_message_group: CanDeleteOwnMessageGroupSchema.exactOptional(),
    can_move_messages_out_of_channel_group: CanMoveMessagesOutOfChannelGroupSchema.exactOptional(),
    can_move_messages_within_channel_group: CanMoveMessagesWithinChannelGroupSchema.exactOptional(),
    can_send_message_group: CanSendMessageGroupSchema.exactOptional(),
    can_subscribe_group: CanSubscribeGroupSchema.exactOptional(),
    can_resolve_topics_group: CanResolveTopicsGroupSchema.exactOptional(),
    can_create_topic_group: CanCreateTopicGroupSchema.exactOptional(),
    subscriber_count: z
      .number()
      .exactOptional()
      .openapi({
        description:
          "The total number of non-deactivated users (including bots) who\nare subscribed to the channel. Clients are responsible for updating\nthis value using `peer_add` and `peer_remove` events.\n\nThe server's internals cannot guarantee this value is correctly\nsynced with `peer_add` and `peer_remove` events for the channel. As\na result, if a (rare) race occurs between a change in the channel's\nsubscribers and fetching this value, it is possible for a client\nthat is correctly following the events protocol to end up with a\npermanently off-by-one error in the channel's subscriber count.\n\nClients are recommended to fetch full subscriber data for a channel\nin contexts where it is important to avoid this risk. The official\nweb application, for example, uses this field primarily while\nwaiting to fetch a given channel's full subscriber list from the\nserver.\n\n**Changes**: New in Zulip 11.0 (feature level 394).\n",
      }),
  })
  .openapi({ description: 'Object containing basic details about the channel.\n', required: [] })
  .openapi('BasicChannelBase')

const BasicChannelSchema = BasicChannelBaseSchema.and(
  z
    .strictObject({
      stream_id: z.any(),
      name: z.any(),
      is_archived: z.any(),
      description: z.any(),
      date_created: z.any(),
      creator_id: z.any().nullable(),
      invite_only: z.any(),
      rendered_description: z.any(),
      is_web_public: z.any(),
      stream_post_policy: z.any(),
      message_retention_days: z.any().nullable(),
      default_push_notifications: z.any(),
      history_public_to_subscribers: z.any(),
      topics_policy: z.any().exactOptional(),
      first_message_id: z.any().nullable(),
      folder_id: z.any().nullable(),
      is_recently_active: z.any(),
      is_announcement_only: z.any(),
      can_add_subscribers_group: z.any().exactOptional(),
      can_remove_subscribers_group: z.any(),
      can_administer_channel_group: z.any().exactOptional(),
      can_delete_any_message_group: z.any().exactOptional(),
      can_delete_own_message_group: z.any().exactOptional(),
      can_move_messages_out_of_channel_group: z.any().exactOptional(),
      can_move_messages_within_channel_group: z.any().exactOptional(),
      can_send_message_group: z.any().exactOptional(),
      can_subscribe_group: z.any(),
      can_resolve_topics_group: z.any().exactOptional(),
      can_create_topic_group: z.any().exactOptional(),
      subscriber_count: z.any(),
      stream_weekly_traffic: z
        .int()
        .nullable()
        .openapi({
          description:
            'The average number of messages sent to the channel per week, as\nestimated based on recent weeks, rounded to the nearest integer.\n\nIf `null`, no information is provided on the average traffic.\nThis can be because the channel was recently created and there\nis insufficient data to make an estimate, or because the server\nwishes to omit this information for this client, this realm, or\nthis endpoint or type of event.\n\n**Changes**: New in Zulip 8.0 (feature level 199). Previously, this\nstatistic was available only in subscription objects.\n',
        }),
    })
    .openapi({
      required: [
        'stream_id',
        'name',
        'is_archived',
        'description',
        'date_created',
        'creator_id',
        'invite_only',
        'rendered_description',
        'is_web_public',
        'stream_post_policy',
        'subscriber_count',
        'message_retention_days',
        'default_push_notifications',
        'history_public_to_subscribers',
        'first_message_id',
        'folder_id',
        'is_recently_active',
        'is_announcement_only',
        'can_remove_subscribers_group',
        'stream_weekly_traffic',
        'can_subscribe_group',
      ],
    }),
).openapi('BasicChannel')

const BotConfigurationSchema = z
  .record(
    z.string(),
    z
      .string()
      .openapi({
        description: '`{config_key}`: Description/value of the configuration data key.\n',
      }),
  )
  .openapi({
    description:
      'A dictionary of string key/value pairs, which describe the configuration\nfor the bot. These are usually details like API keys, and are unique to\nthe integration/bot. Can be an empty dictionary.\n',
  })
  .openapi('BotConfiguration')

const BasicBotBaseSchema = z
  .object({
    user_id: z.int().exactOptional().openapi({ description: 'The user ID of the bot.\n' }),
    default_sending_stream: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({
        description:
          "The default sending channel of the bot. If `null`, the bot doesn't\nhave a default sending channel.\n",
      }),
    default_events_register_stream: z
      .string()
      .nullable()
      .exactOptional()
      .openapi({
        description:
          "The default channel for which the bot receives events/register data.\nIf `null`, the bot doesn't have such a default channel.\n",
      }),
    default_all_public_streams: z
      .boolean()
      .exactOptional()
      .openapi({ description: 'Whether the bot can send messages to all channels by default.\n' }),
    services: z
      .array(
        z
          .xor([
            z
              .strictObject({
                base_url: z
                  .string()
                  .exactOptional()
                  .openapi({
                    description: 'The URL the outgoing webhook is configured to post to.\n',
                  }),
                token: z
                  .string()
                  .exactOptional()
                  .openapi({
                    description:
                      'A unique token that the third-party service can use to confirm\nthat the request is indeed coming from Zulip.\n',
                  }),
                interface: z
                  .int()
                  .exactOptional()
                  .openapi({
                    description:
                      "An integer indicating what format requests are posted in:\n\n- 1 = Zulip's native outgoing webhook format.\n- 2 = Emulate the Slack outgoing webhook format.\n",
                  }),
              })
              .openapi({ description: 'When the bot is an outgoing webhook.\n', required: [] }),
            z
              .strictObject({
                service_name: z
                  .string()
                  .exactOptional()
                  .openapi({ description: 'The name of the bot.\n' }),
                config_data: BotConfigurationSchema.exactOptional(),
              })
              .openapi({ description: 'When the bot is an embedded bot.\n', required: [] }),
          ])
          .openapi({
            description:
              'Object with extra configuration details for the bot. The fields in the\nobject depend on the type of bot.\n',
          }),
      )
      .exactOptional()
      .openapi({
        description:
          'An array containing extra configuration fields only relevant for\noutgoing webhook bots and embedded bots. This is always a single-element\narray.\n\nWe consider this part of the Zulip API to be unstable; it is used only\nfor UI elements for administering bots and is likely to change.\n',
      }),
  })
  .openapi({ required: [] })
  .openapi('BasicBotBase')

