export const postDraftsRoute = createRoute({
  method: 'post',
  path: '/drafts',
  tags: ['drafts'],
  summary: 'Create drafts',
  description:
    'Create one or more drafts on the server. These drafts will be automatically\nsynchronized to other clients via `drafts` events.\n',
  operationId: 'create-drafts',
  request: {
    body: {
      content: {
        'application/x-www-form-urlencoded': {
          schema: z
            .object({
              drafts: z
                .preprocess(
                  (val) => (val === undefined || Array.isArray(val) ? val : [val]),
                  z.array(
                    z
                      .strictObject({
                        id: z
                          .preprocess(
                            (val) =>
                              typeof val === 'string' &&
                              /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                              (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                                ? Number(val)
                                : val,
                            z.int(),
                          )
                          .exactOptional()
                          .openapi({
                            readOnly: true,
                            description: 'The unique ID of the draft.\n',
                          }),
                        type: z
                          .enum(['', 'stream', 'private'])
                          .openapi({
                            description:
                              'The type of the draft. Either unaddressed (empty string), `"stream"`,\nor `"private"` (for one-on-one and group direct messages).\n',
                          }),
                        to: z
                          .preprocess(
                            (val) => (val === undefined || Array.isArray(val) ? val : [val]),
                            z.array(
                              z.preprocess(
                                (val) =>
                                  typeof val === 'string' &&
                                  /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                                  (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                                    ? Number(val)
                                    : val,
                                z.int(),
                              ),
                            ),
                          )
                          .openapi({
                            description:
                              'An array of the tentative target audience IDs. For channel\nmessages, this should contain exactly 1 ID, the ID of the\ntarget channel. For direct messages, this should be an array\nof target user IDs. For unaddressed drafts, this is ignored,\nand clients should send an empty array.\n',
                          }),
                        topic: z
                          .string()
                          .openapi({
                            description:
                              'For channel message drafts, the tentative topic name. For direct\nor unaddressed messages, this will be ignored and should ideally\nbe the empty string. Should not contain null bytes.\n',
                          }),
                        content: z
                          .string()
                          .openapi({
                            description: 'The body of the draft. Should not contain null bytes.\n',
                          }),
                        timestamp: z
                          .preprocess(
                            (val) =>
                              typeof val === 'string' &&
                              /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                              (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                                ? Number(val)
                                : val,
                            z.int(),
                          )
                          .exactOptional()
                          .openapi({
                            description:
                              'A Unix timestamp (seconds only) representing when the draft was\nlast edited. When creating a draft, this key need not be present\nand it will be filled in automatically by the server.\n',
                            example: 1595479019,
                          }),
                      })
                      .openapi({
                        description: 'A dictionary for representing a message draft.\n',
                        required: ['type', 'to', 'topic', 'content'],
                      }),
                  ),
                )
                .exactOptional()
                .openapi({
                  description: 'A JSON-encoded list of containing new draft objects.\n',
                  example: [
                    {
                      type: 'stream',
                      to: [1],
                      topic: 'questions',
                      content: 'What are the contribution guidelines for this project?',
                      timestamp: 1595479019,
                    },
                  ],
                }),
            })
            .openapi({ required: [] }),
          encoding: { drafts: { contentType: 'application/json' } },
        },
      },
    },
  },
  responses: {
    200: {
      description: 'Success.',
      content: {
        'application/json': {
          schema: JsonSuccessBaseSchema.and(
            z
              .strictObject({
                result: z.any().exactOptional(),
                msg: z.any().exactOptional(),
                ignored_parameters_unsupported: z.any().exactOptional(),
                ids: z
                  .array(z.int())
                  .exactOptional()
                  .openapi({
                    description:
                      'An array of the IDs for the drafts that were just created in the same\norder as they were submitted.\n',
                  }),
              })
              .openapi({ example: { result: 'success', msg: '', ids: [1, 2, 3] }, required: [] }),
          ),
        },
      },
    },
    400: {
      description: 'Bad request.',
      content: {
        'application/json': {
          schema: CodedErrorSchema.and(
            z
              .any()
              .openapi({
                description:
                  'JSON response for when a draft targeted towards a channel does not specify\nexactly one channel ID:\n',
                example: {
                  code: 'BAD_REQUEST',
                  msg: 'Must specify exactly 1 channel ID for channel messages',
                  result: 'error',
                },
              }),
          ),
        },
      },
    },
  },
})

