export const postNavigationViewsRoute = createRoute({
  method: 'post',
  path: '/navigation_views',
  tags: ['navigation_views'],
  summary: 'Add a navigation view',
  description:
    'Adds a new custom left sidebar navigation view configuration\nfor the current user.\n\nThis can be used both to configure built-in navigation views,\nor to add new navigation views.\n\n**Changes**: New in Zulip 11.0 (feature level 390).\n',
  operationId: 'add-navigation-view',
  request: {
    body: {
      content: {
        'application/x-www-form-urlencoded': {
          schema: z
            .strictObject({
              fragment: z
                .string()
                .openapi({
                  description:
                    'A unique identifier for the view, used to determine navigation\nbehavior when clicked.\n\nClients should use this value to navigate to the corresponding URL hash.\n',
                  example: 'narrow/is/alerted',
                }),
              is_pinned: z
                .preprocess(
                  ((read) => (val: unknown) => {
                    const result = read.safeParse(val)
                    return result.success ? result.data : val
                  })(z.stringbool()),
                  z.boolean(),
                )
                .openapi({
                  description:
                    'Determines whether the view appears directly in the sidebar or\nis hidden in the "More Views" menu.\n\n- `true` - Pinned and visible in the sidebar.\n- `false` - Hidden and accessible via the "More Views" menu.\n',
                  example: true,
                }),
              name: z
                .string()
                .nullable()
                .exactOptional()
                .openapi({
                  description:
                    'The user-facing name for custom navigation views. Omit this\nfield for built-in views.\n',
                  example: 'Alert Words',
                }),
            })
            .openapi({
              description:
                "Represents a user's personal configuration for a specific\nnavigation view (displayed most visibly at the top of the web\napplication's left sidebar).\n\nNavigation views can be either an override to the default\nbehavior of a built-in view, or a custom view.\n\n**Changes**: New in Zulip 11.0 (feature level 390).\n",
              required: ['fragment', 'is_pinned'],
            }),
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Request succeeded.',
      content: {
        'application/json': {
          schema: JsonSuccessBaseSchema.and(
            z
              .strictObject({ result: z.any().exactOptional(), msg: z.any().exactOptional() })
              .openapi({ example: { result: 'success', msg: '' }, required: [] }),
          ),
        },
      },
    },
    400: {
      description: 'Bad request.',
      content: {
        'application/json': {
          schema: CodedErrorSchema,
          examples: {
            invalid_parameters: {
              value: { code: 'BAD_REQUEST', msg: 'fragment cannot be blank', result: 'error' },
            },
          },
        },
      },
    },
  },
})

