export const patchNavigationViewsFragmentRoute = createRoute({
  method: 'patch',
  path: '/navigation_views/{fragment}',
  tags: ['navigation_views'],
  summary: 'Update the navigation view',
  description:
    "Update the details of an existing configured navigation view,\nsuch as its name or whether it's pinned.\n\n**Changes**: New in Zulip 11.0 (feature level 390).\n",
  operationId: 'edit-navigation-view',
  request: {
    params: z.object({
      fragment: z
        .string()
        .openapi({
          param: {
            name: 'fragment',
            in: 'path',
            required: true,
            schema: { type: 'string' },
            description:
              'The unique URL hash of the navigation view to be updated.\n\nThis also serves as the identifier for the navigation view.\n',
            example: 'narrow/is/alerted',
          },
        }),
    }),
    body: {
      content: {
        'application/x-www-form-urlencoded': {
          schema: z
            .union([
              z
                .unknown()
                .superRefine((val, ctx) => {
                  if (typeof val === 'object' && val !== null && !Array.isArray(val)) {
                    if (!Object.hasOwn(val, 'is_pinned')) {
                      ctx.addIssue({ code: 'custom' })
                    }
                  }
                })
                .openapi({ required: ['is_pinned'] }),
              z
                .unknown()
                .superRefine((val, ctx) => {
                  if (typeof val === 'object' && val !== null && !Array.isArray(val)) {
                    if (!Object.hasOwn(val, 'name')) {
                      ctx.addIssue({ code: 'custom' })
                    }
                  }
                })
                .openapi({ required: ['name'] }),
            ])
            .and(
              z
                .object({
                  is_pinned: z
                    .preprocess(
                      ((read) => (val: unknown) => {
                        const result = read.safeParse(val)
                        return result.success ? result.data : val
                      })(z.stringbool()),
                      z.boolean(),
                    )
                    .exactOptional()
                    .openapi({
                      description:
                        'Determines whether the view is pinned (true) or hidden in\nthe menu (false).\n',
                      example: true,
                    }),
                  name: z
                    .string()
                    .exactOptional()
                    .openapi({
                      description:
                        'The user-facing name for custom navigation views. Omit this\nfield for built-in views.\n',
                      example: 'Watched Phrases',
                    }),
                })
                .openapi({ required: [] }),
            ),
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Success.',
      content: {
        'application/json': {
          schema: JsonSuccessBaseSchema.and(
            z
              .strictObject({ result: z.any().exactOptional(), msg: z.any().exactOptional() })
              .openapi({ example: { result: 'success', msg: '' }, required: [] }),
          ),
        },
      },
    },
    400: {
      description: 'Bad request.',
      content: {
        'application/json': {
          schema: CodedErrorSchema.and(
            z
              .any()
              .openapi({
                example: {
                  code: 'BAD_REQUEST',
                  msg: 'Built-in views cannot have a custom name',
                  result: 'error',
                },
              }),
          ).openapi({ description: 'A typical failed JSON response for invalid parameters.\n' }),
        },
      },
    },
    404: {
      description: 'Not Found.',
      content: {
        'application/json': {
          schema: CodedErrorSchema.and(
            z
              .any()
              .openapi({
                description:
                  'A typical failed JSON response when no navigation view\nexists with the provided fragment:\n',
                example: {
                  code: 'NOT_FOUND',
                  result: 'error',
                  msg: 'Navigation view does not exist.',
                },
              }),
          ),
        },
      },
    },
  },
})

