export const postScheduledMessagesRoute = createRoute({
  method: 'post',
  path: '/scheduled_messages',
  tags: ['scheduled_messages'],
  summary: 'Create a scheduled message',
  description:
    'Create a new [scheduled message](/help/schedule-a-message).\n\n**Changes**: In Zulip 7.0 (feature level 184), moved support for\n[editing a scheduled message](/api/update-scheduled-message) to a\nseparate API endpoint, which removed the `scheduled_message_id`\nparameter from this endpoint.\n\nNew in Zulip 7.0 (feature level 179).\n',
  operationId: 'create-scheduled-message',
  request: {
    body: {
      content: {
        'application/x-www-form-urlencoded': {
          schema: z
            .object({
              type: z
                .enum(['direct', 'channel', 'stream', 'private'])
                .openapi({
                  description:
                    'The type of scheduled message to be sent. `"direct"` for a direct\nmessage and `"stream"` or `"channel"` for a channel message.\n\nNote that, while `"private"` is supported for scheduling direct\nmessages, clients are encouraged to use to the modern convention of\n`"direct"` to indicate this message type, because support for\n`"private"` may eventually be removed.\n\n**Changes**: In Zulip 9.0 (feature level 248), `"channel"` was added as\nan additional value for this parameter to indicate the type of a channel\nmessage.\n',
                  example: 'direct',
                }),
              to: z
                .xor([
                  z.preprocess(
                    (val) =>
                      typeof val === 'string' &&
                      /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                      (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                        ? Number(val)
                        : val,
                    z.int(),
                  ),
                  z.preprocess(
                    (val) => (val === undefined || Array.isArray(val) ? val : [val]),
                    z.array(
                      z.preprocess(
                        (val) =>
                          typeof val === 'string' &&
                          /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                          (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                            ? Number(val)
                            : val,
                        z.int(),
                      ),
                    ),
                  ),
                ])
                .openapi({
                  description:
                    "The scheduled message's tentative target audience.\n\nFor channel messages, the integer ID of the channel.\nFor direct messages, a list containing integer user IDs.\n",
                  example: [9, 10],
                }),
              content: RequiredContentSchema,
              topic: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'The topic of the message. Only required for channel messages\n(`"type": "stream"` or `"type": "channel"`), ignored otherwise.\n\nClients should use the `max_topic_length` returned by the\n[`POST /register`](/api/register-queue) endpoint to determine\nthe maximum topic length.\n\nNote: When `"(no topic)"` or the value of `realm_empty_topic_display_name`\nfound in the [POST /register](/api/register-queue) response is used for this\nparameter, it is interpreted as an empty string.\n\nWhen [topics are required](/help/require-topics), this parameter can\'t\nbe `"(no topic)"`, an empty string, or the value of `realm_empty_topic_display_name`.\n\n**Changes**: Before Zulip 10.0 (feature level 370), `"(no topic)"`\nwas not interpreted as an empty string.\n\nBefore Zulip 10.0 (feature level 334), empty string\nwas not a valid topic name for channel messages.\n',
                  example: 'Castle',
                }),
              scheduled_delivery_timestamp: z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  z.int(),
                )
                .openapi({
                  description:
                    'The UNIX timestamp for when the message will be sent,\nin UTC seconds.\n',
                  example: 3165826990,
                }),
              read_by_sender: z
                .preprocess(
                  ((read) => (val: unknown) => {
                    const result = read.safeParse(val)
                    return result.success ? result.data : val
                  })(z.stringbool()),
                  z.boolean(),
                )
                .exactOptional()
                .openapi({
                  description:
                    'Whether the message should be initially marked read by its\nsender. If unspecified, the server uses a heuristic based\non the client name and the recipient.\n\n**Changes**: New in Zulip 8.0 (feature level 236).\n',
                  example: true,
                }),
            })
            .openapi({ required: ['type', 'to', 'content', 'scheduled_delivery_timestamp'] }),
          encoding: {
            to: { contentType: 'application/json' },
            scheduled_delivery_timestamp: { contentType: 'application/json' },
            read_by_sender: { contentType: 'application/json' },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Success.',
      content: {
        'application/json': {
          schema: JsonSuccessBaseSchema.and(
            z
              .strictObject({
                result: z.any().exactOptional(),
                msg: z.any().exactOptional(),
                ignored_parameters_unsupported: z.any().exactOptional(),
                scheduled_message_id: z
                  .int()
                  .exactOptional()
                  .openapi({
                    description:
                      'The unique ID of the scheduled message.\n\nThis is different from the unique ID that the message will have\nafter it is sent.\n',
                  }),
              })
              .openapi({
                example: { msg: '', scheduled_message_id: 42, result: 'success' },
                required: [],
              }),
          ),
        },
      },
    },
    400: {
      description: 'Bad request.',
      content: {
        'application/json': {
          schema: z.xor([
            NonExistingChannelIdErrorSchema.and(
              z
                .any()
                .openapi({
                  description:
                    'A typical failed JSON response for when a channel message is scheduled\nto be sent to a channel that does not exist:\n',
                }),
            ),
            CodedErrorSchema.and(
              z
                .any()
                .openapi({
                  example: { code: 'BAD_REQUEST', msg: 'Invalid user ID 10', result: 'error' },
                  description:
                    'A typical failed JSON response for when a direct message is scheduled\nto be sent to a user that does not exist:\n',
                }),
            ),
          ]),
        },
      },
    },
  },
})

