export const getMessagesMessageIdReadReceiptsRoute = createRoute({
  method: 'get',
  path: '/messages/{message_id}/read_receipts',
  tags: ['messages'],
  summary: "Get a message's read receipts",
  description:
    "Returns a list containing the IDs for all users who have\nmarked the message as read (and whose privacy settings allow\nsharing that information).\n\nThe list of users IDs will include any bots who have marked\nthe message as read via the API (providing a way for bots to\nindicate whether they have processed a message successfully in\na way that can be easily inspected in a Zulip client). Bots\nfor which this behavior is not desired may disable the\n`send_read_receipts` setting via the API.\n\nIt will never contain the message's sender.\n\n**Changes**: New in Zulip 6.0 (feature level 137).\n",
  operationId: 'get-read-receipts',
  request: { params: z.object({ message_id: MessageIdParamsSchema }) },
  responses: {
    200: {
      description: 'Success.',
      content: {
        'application/json': {
          schema: JsonSuccessBaseSchema.and(
            z
              .strictObject({
                result: z.any().exactOptional(),
                msg: z.any().exactOptional(),
                ignored_parameters_unsupported: z.any().exactOptional(),
                user_ids: z
                  .array(z.int())
                  .exactOptional()
                  .openapi({
                    description:
                      'An array of IDs of users who have marked the target message as\nread and whose read status is available to the current user.\n\nThe IDs of users who have disabled sending read receipts\n(`"send_read_receipts": false`) will never appear in the response,\nnor will the message\'s sender. Additionally, the IDs of any users\nwho have been muted by the current user or who have muted the\ncurrent user will not be included in the response.\n\nThe current user\'s ID will appear if they have marked the target\nmessage as read.\n\n**Changes**: Prior to Zulip 6.0 (feature level 143), the IDs of\nusers who have been muted by or have muted the current user were\nincluded in the response.\n',
                  }),
              })
              .openapi({
                example: { msg: '', result: 'success', user_ids: [3, 7, 9] },
                required: [],
              }),
          ),
        },
      },
    },
    400: {
      description: 'Bad request.',
      content: {
        'application/json': {
          schema: InvalidMessageErrorSchema.and(
            z
              .any()
              .openapi({
                description:
                  'A typical JSON response when attempting to access read receipts for\na message ID that either does not exist or is not accessible to the\ncurrent user:\n',
              }),
          ),
        },
      },
    },
  },
})

export const getMessagesMatchesNarrowRoute = createRoute({
  method: 'get',
  path: '/messages/matches_narrow',
  tags: ['messages'],
  summary: 'Check if messages match a narrow',
  description:
    'Check whether a set of messages match a [narrow](/api/construct-narrow).\n\nFor many common narrows (e.g. a topic), clients can write an efficient\nclient-side check to determine whether a newly arrived message belongs\nin the view.\n\nThis endpoint is designed to allow clients to handle more complex narrows\nfor which the client does not (or in the case of full-text search, cannot)\nimplement this check.\n\nThe format of the `match_subject` and `match_content` objects is designed\nto match those returned by the [`GET /messages`](/api/get-messages#response)\nendpoint, so that a client can splice these fields into a `message` object\nreceived from [`GET /events`](/api/get-events#message) and end up with an\nextended message object identical to how a [`GET /messages`](/api/get-messages)\nrequest for the current narrow would have returned the message.\n',
  operationId: 'check-messages-match-narrow',
  request: {
    query: z.object({
      msg_ids: z
        .preprocess((val) => {
          if (typeof val !== 'string') return val
          try {
            return JSON.parse(val)
          } catch {
            return val
          }
        }, z.array(z.int()))
        .openapi({
          param: {
            name: 'msg_ids',
            in: 'query',
            description: 'List of IDs for the messages to check.',
            content: {
              'application/json': {
                schema: { type: 'array', items: { type: 'integer' } },
                example: [31, 32],
              },
            },
            required: true,
          },
        }),
      narrow: z
        .preprocess(
          (val) => {
            if (typeof val !== 'string') return val
            try {
              return JSON.parse(val)
            } catch {
              return val
            }
          },
          z.array(z.object({})),
        )
        .openapi({
          param: {
            name: 'narrow',
            in: 'query',
            description:
              'A structure defining the narrow to check against. See how to\n[construct a narrow](/api/construct-narrow).\n\n**Changes**: See [changes section](/api/construct-narrow#changes)\nof search/narrow filter documentation.\n',
            content: {
              'application/json': {
                schema: { type: 'array', items: { type: 'object' } },
                example: [{ operator: 'has', operand: 'link' }],
              },
            },
            required: true,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Success.',
      content: {
        'application/json': {
          schema: JsonSuccessBaseSchema.and(
            z
              .strictObject({
                result: z.any().exactOptional(),
                msg: z.any().exactOptional(),
                ignored_parameters_unsupported: z.any().exactOptional(),
                messages: z
                  .record(
                    z.string(),
                    z
                      .strictObject({
                        match_content: z
                          .string()
                          .exactOptional()
                          .openapi({
                            description:
                              'HTML content of a queried message that matches the narrow. If the\nnarrow is a search narrow, `<span class="highlight">` elements\nwill be included, wrapping the matches for the search keywords.\n',
                          }),
                        match_subject: z
                          .string()
                          .exactOptional()
                          .openapi({
                            description:
                              'HTML-escaped topic of a queried message that matches the narrow. If the\nnarrow is a search narrow, `<span class="highlight">` elements\nwill be included wrapping the matches for the search keywords.\n',
                          }),
                      })
                      .openapi({
                        description:
                          '`message_id`: The ID of the message that matches the narrow. No record will be returned\nfor queried messages that do not match the narrow.\n',
                        required: [],
                      }),
                  )
                  .exactOptional()
                  .openapi({
                    description:
                      'A dictionary with a key for each queried message that matches the narrow,\nwith message IDs as keys and search rendering data as values.\n',
                  }),
              })
              .openapi({
                example: {
                  result: 'success',
                  msg: '',
                  messages: {
                    '31': {
                      match_content:
                        '<p><a href="http://foo.com" target="_blank" title="http://foo.com">http://foo.com</a></p>',
                      match_subject: 'test_topic',
                    },
                  },
                },
                required: [],
              }),
          ),
        },
      },
    },
  },
})

export const getMessagesMessageIdRoute = createRoute({
  method: 'get',
  path: '/messages/{message_id}',
  tags: ['messages'],
  summary: 'Fetch a single message',
  description:
    "Given a message ID, return the message object.\n\nAdditionally, a `raw_content` field is included. This field is\nuseful for clients that primarily work with HTML-rendered\nmessages but might need to occasionally fetch the message's\nraw [Zulip-flavored Markdown](/help/format-your-message-using-markdown) (e.g. for [view\nsource](/help/view-the-markdown-source-of-a-message) or\nprefilling a message edit textarea).\n\n**Changes**: Before Zulip 5.0 (feature level 120), this\nendpoint only returned the `raw_content` field.\n",
  operationId: 'get-message',
  request: {
    params: z.object({ message_id: MessageIdParamsSchema }),
    query: z.object({
      apply_markdown: z
        .stringbool()
        .default(true)
        .exactOptional()
        .openapi({
          param: {
            name: 'apply_markdown',
            in: 'query',
            description:
              'If `true`, message content is returned in the rendered HTML\nformat. If `false`, message content is returned in the raw\n[Zulip-flavored Markdown format](/help/format-your-message-using-markdown) text that user entered.\n\n**Changes**: New in Zulip 5.0 (feature level 120).\n',
            schema: { type: 'boolean', default: true },
            example: false,
            required: false,
          },
        }),
      allow_empty_topic_name: z
        .stringbool()
        .default(false)
        .exactOptional()
        .openapi({
          param: {
            name: 'allow_empty_topic_name',
            in: 'query',
            description:
              'Whether the client supports processing the empty string as a topic in the\ntopic name fields in the returned data, including in returned edit_history data.\n\nIf `false`, the server will use the value of `realm_empty_topic_display_name`\nfound in the [`POST /register`](/api/register-queue) response instead of empty string\nto represent the empty string topic in its response.\n\n**Changes**: New in Zulip 10.0 (feature level 334). Previously, the empty string\nwas not a valid topic.\n',
            schema: { type: 'boolean', default: false },
            example: true,
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Success.',
      content: {
        'application/json': {
          schema: JsonSuccessBaseSchema.and(
            z
              .strictObject({
                result: z.any().exactOptional(),
                msg: z.any().exactOptional(),
                ignored_parameters_unsupported: z.any().exactOptional(),
                raw_content: z
                  .string()
                  .exactOptional()
                  .openapi({
                    deprecated: true,
                    description:
                      'The raw Markdown content of the message.\n\nSee the help center article on [message formatting](/help/format-your-message-using-markdown) for details on Zulip-flavored Markdown.\n\n**Deprecated** and to be removed once no longer required for\nlegacy clients. Modern clients should prefer passing\n`"apply_markdown": false` to request raw message content.\n',
                  }),
                message: MessagesBaseSchema.and(
                  z
                    .strictObject({
                      avatar_url: z.any().nullable().exactOptional(),
                      client: z.any().exactOptional(),
                      content: z.any().exactOptional(),
                      content_type: z.any().exactOptional(),
                      display_recipient: z.any().exactOptional(),
                      edit_history: z.any().exactOptional(),
                      id: z.any().exactOptional(),
                      is_me_message: z.any().exactOptional(),
                      last_edit_timestamp: z.any().exactOptional(),
                      last_moved_timestamp: z.any().exactOptional(),
                      reactions: z.any().exactOptional(),
                      recipient_id: z.any().exactOptional(),
                      sender_email: z.any().exactOptional(),
                      sender_full_name: z.any().exactOptional(),
                      sender_id: z.any().exactOptional(),
                      sender_realm_str: z.any().exactOptional(),
                      stream_id: z.any().exactOptional(),
                      subject: z.any().exactOptional(),
                      submessages: z.any().exactOptional(),
                      timestamp: z.any().exactOptional(),
                      topic_links: z.any().exactOptional(),
                      type: z.any().exactOptional(),
                      flags: z
                        .array(z.string())
                        .exactOptional()
                        .openapi({
                          description:
                            "The user's [message flags][message-flags] for the message.\n\n**Changes**: In Zulip 8.0 (feature level 224), the `wildcard_mentioned`\nflag was deprecated in favor of the `stream_wildcard_mentioned` and\n`topic_wildcard_mentioned` flags. The `wildcard_mentioned` flag exists\nfor backwards compatibility with older clients and equals\n`stream_wildcard_mentioned || topic_wildcard_mentioned`. Clients\nsupporting older server versions should treat this field as a previous\nname for the `stream_wildcard_mentioned` flag as topic wildcard mentions\nwere not available prior to this feature level.\n\n[message-flags]: /api/update-message-flags#available-flags\n",
                        }),
                    })
                    .openapi({ required: [] }),
                )
                  .exactOptional()
                  .openapi({
                    description:
                      'An object containing details of the message.\n\n**Changes**: New in Zulip 5.0 (feature level 120).\n',
                  }),
              })
              .openapi({
                example: {
                  raw_content: "**Don't** forget your towel!",
                  result: 'success',
                  msg: '',
                  message: {
                    subject: '',
                    sender_realm_str: 'zulip',
                    type: 'private',
                    content:
                      '<p>Security experts agree that relational algorithms are an interesting new topic in the field of networking, and scholars concur.</p>',
                    flags: ['read'],
                    id: 16,
                    display_recipient: [
                      {
                        id: 4,
                        is_mirror_dummy: false,
                        email: 'hamlet@zulip.com',
                        full_name: 'King Hamlet',
                      },
                      { id: 5, is_mirror_dummy: false, email: 'iago@zulip.com', full_name: 'Iago' },
                      {
                        id: 8,
                        is_mirror_dummy: false,
                        email: 'prospero@zulip.com',
                        full_name: 'Prospero from The Tempest',
                      },
                    ],
                    content_type: 'text/html',
                    is_me_message: false,
                    timestamp: 1527921326,
                    sender_id: 4,
                    sender_full_name: 'King Hamlet',
                    recipient_id: 27,
                    topic_links: [],
                    client: 'ZulipDataImport',
                    avatar_url:
                      'https://secure.gravatar.com/avatar/6d8cad0fd00256e7b40691d27ddfd466?d=identicon&version=1',
                    submessages: [],
                    sender_email: 'hamlet@zulip.com',
                    reactions: [],
                  },
                },
                required: [],
              }),
          ),
        },
      },
    },
    400: {
      description: 'Bad request.',
      content: {
        'application/json': {
          schema: InvalidMessageErrorSchema.and(
            z
              .any()
              .openapi({
                description:
                  'An example JSON response for when the specified message does not exist or it\nis not visible to the user making the query (e.g. it was a direct message\nbetween two other users):\n',
              }),
          ),
        },
      },
    },
  },
})

export const deleteMessagesMessageIdRoute = createRoute({
  method: 'delete',
  path: '/messages/{message_id}',
  tags: ['messages'],
  summary: 'Delete a message',
  description:
    'Permanently delete a message.\n\nThis API corresponds to the [delete a message completely][delete-completely]\nfeature documented in the Zulip help center.\n\nA user must be able to access the content of a message in order to delete it.\nSee [channel permissions](/help/channel-permissions) for more information\nabout content access for channel messages. For direct messages, the user\nmust have received or sent the direct message to have content access.\n\nSee [restricting message deletion](/help/restrict-message-editing-and-deletion)\nfor documentation on when users are allowed to delete messages.\n\nThe relevant realm settings in the API that are related to the above linked\ndocumentation on when users are allowed to delete messages are:\n\n- `realm_can_delete_any_message_group`\n- `realm_can_delete_own_message_group`\n- `realm_can_set_delete_message_policy_group`\n- `realm_message_content_delete_limit_seconds`\n\nThe relevant per-channel permission settings in the API that are related to the\nabove linked documentation on when users are allowed to delete messages in a\nspecific channel are:\n\n- `can_delete_any_message_group`\n- `can_delete_own_message_group`\n\nMore details about these realm and channel settings can be found in the\n[`POST /register`](/api/register-queue) response.\n\n**Changes**: Prior to Zulip 10.0 (feature level 281), only organization\nadministrators had permission to permanently delete a message.\n\n[delete-completely]: /help/delete-a-message#delete-a-message-completely\n',
  operationId: 'delete-message',
  request: { params: z.object({ message_id: MessageIdParamsSchema }) },
  responses: {
    200: SimpleSuccessResponse,
    400: {
      description: 'Bad request.',
      content: {
        'application/json': {
          schema: z.xor([
            InvalidMessageErrorSchema.and(
              z
                .any()
                .openapi({
                  description:
                    'An example JSON response for when the specified message does not exist:\n',
                }),
            ),
            CodedErrorSchema.and(
              z
                .any()
                .openapi({
                  description:
                    'An example JSON response for when the user making the query does not\nhave permission to delete the message:\n',
                  example: {
                    code: 'BAD_REQUEST',
                    msg: "You don't have permission to delete this message",
                    result: 'error',
                  },
                }),
            ),
          ]),
        },
      },
    },
  },
})

export const patchMessagesMessageIdRoute = createRoute({
  method: 'patch',
  path: '/messages/{message_id}',
  tags: ['messages'],
  summary: 'Edit a message',
  description:
    'Update the content, topic, or channel of the message with the specified\nID.\n\nYou can [resolve topics](/help/resolve-a-topic) by editing the topic to\n`✔ {original_topic}` with the `propagate_mode` parameter set to\n`"change_all"`.\n\nSee [configuring message editing][config-message-editing] for detailed\ndocumentation on when users are allowed to edit message content, and\n[restricting moving messages][restrict-move-messages] for detailed\ndocumentation on when users are allowed to change a message\'s topic\nand/or channel.\n\nThe relevant realm settings in the API that are related to the above\nlinked documentation on when users are allowed to update messages are:\n\n- `allow_message_editing`\n- `can_resolve_topics_group`\n- `can_move_messages_between_channels_group`\n- `can_move_messages_between_topics_group`\n- `message_content_edit_limit_seconds`\n- `move_messages_within_stream_limit_seconds`\n- `move_messages_between_streams_limit_seconds`\n\nMore details about these realm settings can be found in the\n[`POST /register`](/api/register-queue) response or in the documentation\nof the [`realm op: update_dict`](/api/get-events#realm-update_dict)\nevent in [`GET /events`](/api/get-events).\n\n**Changes**: Prior to Zulip 10.0 (feature level 367), the permission for\nresolving a topic was managed by `can_move_messages_between_topics_group`.\nAs of this feature level, users belonging to the `can_resolve_topics_group`\nwill have the permission to [resolve topics](/help/resolve-a-topic) in the organization.\n\nIn Zulip 10.0 (feature level 316), `edit_topic_policy`\nwas removed and replaced by `can_move_messages_between_topics_group`\nrealm setting.\n\n**Changes**: In Zulip 10.0 (feature level 310), `move_messages_between_streams_policy`\nwas removed and replaced by `can_move_messages_between_channels_group`\nrealm setting.\n\nPrior to Zulip 7.0 (feature level 172), anyone could add a\ntopic to channel messages without a topic, regardless of the organization\'s\n[topic editing permissions](/help/restrict-moving-messages). As of this\nfeature level, messages without topics have the same restrictions for\ntopic edits as messages with topics.\n\nBefore Zulip 7.0 (feature level 172), by using the `change_all` value for\nthe `propagate_mode` parameter, users could move messages after the\norganization\'s configured time limits for changing a message\'s topic or\nchannel had passed. As of this feature level, the server will [return an\nerror](/api/update-message#response) with `"code":\n"MOVE_MESSAGES_TIME_LIMIT_EXCEEDED"` if users, other than organization\nadministrators or moderators, try to move messages after these time\nlimits have passed.\n\nBefore Zulip 7.0 (feature level 162), users who were not administrators or\nmoderators could only edit topics if the target message was sent within the\nlast 3 days. As of this feature level, that time limit is now controlled by\nthe realm setting `move_messages_within_stream_limit_seconds`. Also at this\nfeature level, a similar time limit for moving messages between channels was\nadded, controlled by the realm setting\n`move_messages_between_streams_limit_seconds`. Previously, all users who\nhad permission to move messages between channels did not have any time limit\nrestrictions when doing so.\n\nBefore Zulip 7.0 (feature level 159), editing channels and topics of messages\nwas forbidden if the realm setting for `allow_message_editing` was `false`,\nregardless of an organization\'s configuration for the realm settings\n`edit_topic_policy` or `move_messages_between_streams_policy`.\n\nBefore Zulip 7.0 (feature level 159), message senders were allowed to edit\nthe topic of their messages indefinitely.\n\nIn Zulip 5.0 (feature level 75), the `edit_topic_policy` realm setting\nwas added, replacing the `allow_community_topic_editing` boolean.\n\nIn Zulip 4.0 (feature level 56), the `move_messages_between_streams_policy`\nrealm setting was added.\n\n[config-message-editing]: /help/restrict-message-editing-and-deletion\n[restrict-move-messages]: /help/restrict-moving-messages\n',
  operationId: 'update-message',
  request: {
    params: z.object({ message_id: MessageIdParamsSchema }),
    body: {
      content: {
        'application/x-www-form-urlencoded': {
          schema: z
            .object({
              topic: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'The topic to move the message(s) to, to request changing the topic.\n\nClients should use the `max_topic_length` returned by the\n[`POST /register`](/api/register-queue) endpoint to determine\nthe maximum topic length\n\nShould only be sent when changing the topic, and will throw an error\nif the target message is not a channel message.\n\nNote: When the value of `realm_empty_topic_display_name` found in\nthe [POST /register](/api/register-queue) response is used for this\nparameter, it is interpreted as an empty string.\n\nWhen [topics are required](/help/require-topics), this parameter can\'t\nbe `"(no topic)"`, an empty string, or the value of `realm_empty_topic_display_name`.\n\nYou can [resolve topics](/help/resolve-a-topic) by editing the topic to\n`✔ {original_topic}` with the `propagate_mode` parameter set to\n`"change_all"`. The empty string topic cannot be marked as resolved.\n\n**Changes**: Before Zulip 10.0 (feature level 334), empty string\nwas not a valid topic name for channel messages.\n\nNew in Zulip 2.0.0. Previous Zulip releases encoded this as `subject`,\nwhich is currently a deprecated alias.\n',
                  example: 'Castle',
                }),
              propagate_mode: z
                .enum(['change_one', 'change_later', 'change_all'])
                .default('change_one')
                .exactOptional()
                .openapi({
                  description:
                    'Which message(s) should be edited:\n\n- `"change_later"`: The target message and all following messages.\n- `"change_one"`: Only the target message.\n- `"change_all"`: All messages in this topic.\n\nOnly the default value of `"change_one"` is valid when editing\nonly the content of a message.\n\nThis parameter determines both which messages get moved and also whether\nclients that are currently narrowed to the topic containing the message\nshould navigate or adjust their compose box recipient to point to the\npost-edit channel/topic.\n',
                  example: 'change_all',
                }),
              send_notification_to_old_thread: z
                .preprocess(
                  ((read) => (val: unknown) => {
                    const result = read.safeParse(val)
                    return result.success ? result.data : val
                  })(z.stringbool()),
                  z.boolean(),
                )
                .default(false)
                .exactOptional()
                .openapi({
                  description:
                    'Whether to send an automated message to the old topic to\nnotify users where the messages were moved to.\n\n**Changes**: Before Zulip 6.0 (feature level 152), this parameter\nhad a default of `true` and was ignored unless the channel was changed.\n\nNew in Zulip 3.0 (feature level 9).\n',
                  example: true,
                }),
              send_notification_to_new_thread: z
                .preprocess(
                  ((read) => (val: unknown) => {
                    const result = read.safeParse(val)
                    return result.success ? result.data : val
                  })(z.stringbool()),
                  z.boolean(),
                )
                .default(true)
                .exactOptional()
                .openapi({
                  description:
                    'Whether to send an automated message to the new topic to\nnotify users where the messages came from.\n\nIf the move is just [resolving/unresolving a topic](/help/resolve-a-topic),\nthis parameter will not trigger an additional notification.\n\n**Changes**: Before Zulip 6.0 (feature level 152), this parameter\nwas ignored unless the channel was changed.\n\nNew in Zulip 3.0 (feature level 9).\n',
                  example: true,
                }),
              content: OptionalContentSchema.exactOptional(),
              prev_content_sha256: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    "An optional SHA-256 hash of the previous raw content of the message\nthat the client has at the time of the request.\n\nIf provided, the server will return an error if it does not match the\nSHA-256 hash of the message's content stored in the database.\n\nClients can use this feature to prevent races where multiple clients\nsave conflicting edits to a message.\n\n**Changes**: New in Zulip 11.0 (feature level 379).\n",
                  example: '6ae8a75555209fd6c44157c0aed8016e763ff435a19cf186f76863140143ff72',
                }),
              stream_id: z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  z.int(),
                )
                .exactOptional()
                .openapi({
                  description:
                    "The channel ID to move the message(s) to, to request moving\nmessages to another channel.\n\nShould only be sent when changing the channel. Will throw an error\nif the target message is not a channel message.\n\nNote that a message's content and channel cannot be changed at the\nsame time, so sending both `content` and `stream_id` parameters will\nthrow an error.\n\n**Changes**: Prior to Zulip 13.0 (feature level 509), passing the channel\nID that the target message is currently in was processed as a successful\nchannel move, even if the target message was not moved (i.e., neither its\nchannel nor topic were changed).\n\nNew in Zulip 3.0 (feature level 1).\n",
                  example: 43,
                }),
            })
            .openapi({ required: [] }),
          encoding: {
            send_notification_to_old_thread: { contentType: 'application/json' },
            send_notification_to_new_thread: { contentType: 'application/json' },
            stream_id: { contentType: 'application/json' },
          },
        },
      },
    },
  },
  responses: {
    200: {
      description: 'Success.',
      content: {
        'application/json': {
          schema: JsonSuccessBaseSchema.and(
            z
              .strictObject({
                result: z.any().exactOptional(),
                msg: z.any().exactOptional(),
                ignored_parameters_unsupported: z.any().exactOptional(),
                detached_uploads: z
                  .array(AttachmentSchema)
                  .exactOptional()
                  .openapi({
                    description:
                      'Details on all files uploaded by the acting user whose only references\nwere removed when editing this message. Clients should ask the acting user\nif they wish to delete the uploaded files returned in this response,\nwhich might otherwise remain visible only in message edit history.\n\nNote that [access to message edit history][edit-history-access]\nis configurable; this detail may be important in presenting the\nquestion clearly to users.\n\nNew in Zulip 10.0 (feature level 285).\n\n[edit-history-access]: /help/restrict-message-edit-history-access\n',
                  }),
              })
              .openapi({
                example: {
                  result: 'success',
                  msg: '',
                  detached_uploads: [
                    {
                      id: 3,
                      name: '1253601-1.jpg',
                      path_id: '2/5d/BD5NRptFxPDKY3RUKwhhup8r/1253601-1.jpg',
                      size: 1339060,
                      create_time: 1687984706,
                      message_ids: [],
                    },
                  ],
                },
                required: [],
              }),
          ),
        },
      },
    },
    400: {
      description: 'Bad request.',
      content: {
        'application/json': {
          schema: z.xor([
            CodedErrorSchema.and(
              z
                .object({
                  msg: z
                    .enum([
                      'Your organization has turned off message editing',
                      "You don't have permission to edit this message",
                      'The time limit for editing this message has past',
                      'Nothing to change',
                      "Topic can't be empty",
                    ])
                    .exactOptional(),
                })
                .openapi({
                  example: {
                    code: 'BAD_REQUEST',
                    msg: "You don't have permission to edit this message",
                    result: 'error',
                  },
                  description:
                    "A typical JSON response for when one doesn't have the permission to\nedit a particular message:\n",
                  required: [],
                }),
            ),
            CodedErrorSchema.and(
              z
                .any()
                .openapi({
                  example: {
                    code: 'MOVE_MESSAGES_TIME_LIMIT_EXCEEDED',
                    first_message_id_allowed_to_move: 123,
                    msg: 'You only have permission to move the 2/5 most recent messages in this topic.',
                    result: 'error',
                    total_messages_allowed_to_move: 2,
                    total_messages_in_topic: 5,
                  },
                  description:
                    'A special failed JSON response (`"code": "MOVE_MESSAGES_TIME_LIMIT_EXCEEDED"`)\nfor when the user asked to move all messages in a topic\n(`"propagate_mode": "change_all"`) and the user can move at least one message\nbut does not have permission to move the entire topic.\n\nThis happens when the topic contains some messages that are older than an\napplicable time limit for the requested topic move (see\n`move_messages_within_stream_limit_seconds` and/or\n`move_messages_between_streams_limit_seconds` in the\n[`POST /register`](/api/register-queue) response).\n\nThe error response contains data on which portion of this topic the user has\npermission to move. `first_message_id_allowed_to_move` is the oldest message\nID in this topic that the user has permission to move.\nThere are `total_messages_in_topic` in the topic, but the user only has\npermission to move the (most recent) `total_messages_allowed_to_move`\nmessages.\n\nClients should support this error code with\n`"first_message_id_allowed_to_move": null` for forward compatibility\nwith future server versions that may use this error code with other\npropagation modes where the user does not have permission to move any\nmessages, or where the server did not calculate the total message counts\nnoted above.\n\nClients can either only present the error to the user or, if\n`first_message_id_allowed_to_move` is not `null`, prompt the user to adjust\ntheir query with the above information.\n\nIf clients choose to present a prompt for this error code, they should\nrecommend the option of cancelling and (manually) asking a moderator to\nmove the entire topic, since that\'s often a better experience than\npartially moving a topic. This API supports a client that wishes to allow\nthe user to repeat the request with a `change_later` propagation mode and\na target message ID of `first_message_id_allowed_to_move`, if the user\ndesires to move only the portion of the topic that they can.\n\nNote that in a [private channel with protected history][private-channels],\nthe Zulip security model requires that the above calculations only include\nmessages the acting user has access to. So in the rare case of a user\nattempting to move a topic that started before the user joined a private\nchannel with protected history, this API endpoint might move only the portion\nof a topic that they have access to, without this error or any confirmation\ndialog.\n\n**Changes**: Before Zulip 13.0 (feature level 505), this error\nresponse was only returned when the request\'s target message was\nitself within the time limit. As of this feature level, it is also\nreturned when the target message is past the limit but at least one\nmessage in the topic is within it.\n\nNew in Zulip 7.0 (feature level 172).\n\n[private-channels]: /help/channel-permissions#private-channels\n',
                }),
            ),
            CodedErrorSchema.and(
              z
                .any()
                .openapi({
                  example: {
                    result: 'error',
                    msg: 'You do not have permission to use channel wildcard mentions in this channel.',
                    code: 'STREAM_WILDCARD_MENTION_NOT_ALLOWED',
                  },
                  description:
                    'An example JSON error response for when the message was rejected because\nthe message contains a stream wildcard mention, but the user doesn\'t have\npermission to use such a mention in this channel as the user is not present\nin `can_mention_many_users_group` and the channel contains a large number\nof subscribers.\n\n**Changes**: New in Zulip 8.0 (feature level 229). Previously, this\nerror returned the `"BAD_REQUEST"` code.\n',
                }),
            ),
            CodedErrorSchema.and(
              z
                .any()
                .openapi({
                  example: {
                    result: 'error',
                    msg: 'You do not have permission to use topic wildcard mentions in this topic.',
                    code: 'TOPIC_WILDCARD_MENTION_NOT_ALLOWED',
                  },
                  description:
                    "An example JSON error response for when the message was rejected because\nthe message contains a topic wildcard mention, but the user doesn't have\npermission to use such a mention in this topic as the user is not present\nin `can_mention_many_users_group` and the topic contains a large number\nof participants.\n\n**Changes**: New in Zulip 8.0 (feature level 229). Previously,\n`wildcard_mention_policy` was not enforced for topic mentions.\n",
                }),
            ),
          ]),
        },
      },
    },
  },
})

export const postMessagesMessageIdReportRoute = createRoute({
  method: 'post',
  path: '/messages/{message_id}/report',
  tags: ['messages'],
  summary: 'Report a message',
  description:
    'Sends a notification to the organization\'s [moderation request\nchannel](/help/enable-moderation-requests), if it is configured, that\nreports the targeted message for [review and moderation](/help/report-a-message).\n\nClients should check the `moderation_request_channel` realm setting to\ndecide whether to show the option to report messages in the UI.\n\nIf the `report_type` parameter value is `"other"`, the `description`\nparameter is required. Clients should also enforce and communicate this\nbehavior in the UI.\n\n**Changes**: Before Zulip 13.0 (feature level 511), this endpoint\ndid not return an error if the message report failed to be sent to the\nmoderation request channel.\n\nNew in Zulip 11.0 (feature level 382). This API builds on the\n`moderation_request_channel` realm setting, which was added in\nfeature level 331.\n',
  operationId: 'report-message',
  request: {
    params: z.object({ message_id: MessageIdParamsSchema }),
    body: {
      content: {
        'application/x-www-form-urlencoded': {
          schema: z
            .object({
              report_type: z
                .string()
                .openapi({
                  description:
                    'The reason that best describes why the current user is reporting the\ntarget message for moderation.\n\nMust be one of the `key` values in the `server_report_message_types`\nfield in the [`POST /register`](/api/register-queue) response.\n\n**Changes**: Prior to Zulip 12.0 (feature level 435), the allowed\nvalues for this parameter were limited to: `"harassment"`,\n`"inappropriate"`, `"norms"`, `"other"`, `"spam"`.\n',
                  example: 'harassment',
                }),
              description: z
                .string()
                .exactOptional()
                .openapi({
                  description:
                    'A short description with additional context about why the current user\nis reporting the target message for moderation.\n\nClients should limit this string to 1000 Unicode code points.\n\nIf the `report_type` parameter is `"other"`, this parameter is required,\nand its value cannot be an empty string.\n',
                  example:
                    'This message insults and mocks Frodo, which is against the code of conduct.',
                }),
            })
            .openapi({ required: ['report_type'] }),
        },
      },
      required: true,
    },
  },
  responses: {
    200: SimpleSuccessResponse,
    400: {
      description: 'Bad request.',
      content: {
        'application/json': {
          schema: CodedErrorSchema.and(
            z
              .any()
              .openapi({
                example: {
                  result: 'error',
                  msg: 'Moderation request channel must be specified to enable message reporting.',
                  code: 'BAD_REQUEST',
                },
                description:
                  "An example JSON error response for when the organization's moderation\nrequest channel is not configured:\n",
              }),
          ),
        },
      },
    },
  },
})

export const postUserUploadsRoute = createRoute({
  method: 'post',
  path: '/user_uploads',
  tags: ['messages'],
  summary: 'Upload a file',
  description:
    "[Upload](/help/share-and-upload-files) a single file and get the corresponding URL.\n\nInitially, only you will be able to access the link. To share the\nuploaded file, you'll need to [send a message][send-message]\ncontaining the resulting link. Users who can already access the link\ncan reshare it with other users by sending additional Zulip messages\ncontaining the link.\n\nThe maximum allowed file size is available in the `max_file_upload_size_mib`\nfield in the [`POST /register`](/api/register-queue) response. Note that\nlarge files (25MB+) may fail to upload using this API endpoint due to\nnetwork-layer timeouts, depending on the quality of your connection to the\nZulip server.\n\nFor uploading larger files, `/api/v1/tus` is an endpoint implementing the\n[`tus` resumable upload protocol](https://tus.io/protocols/resumable-upload),\nwhich supports uploading arbitrarily large files limited only by the server's\n`max_file_upload_size_mib` (Configured via `MAX_FILE_UPLOAD_SIZE` in\n`/etc/zulip/settings.py`). Clients which send authenticated credentials\n(either via browser-based cookies, or API key via `Authorization` header) may\nuse this endpoint to upload files.\n\n**Changes**: The `api/v1/tus` endpoint supporting resumable uploads was\nintroduced in Zulip 10.0 (feature level 296). Previously,\n`max_file_upload_size_mib` was typically 25MB.\n\n[uploaded-files]: /help/manage-your-uploaded-files\n[send-message]: /api/send-message\n",
  operationId: 'upload-file',
  request: {
    body: {
      content: {
        'multipart/form-data': {
          schema: z
            .object({
              filename: z
                .file()
                .exactOptional()
                .openapi({ type: 'string', format: 'binary', example: '/path/to/file' }),
            })
            .openapi({ required: [] }),
        },
      },
    },
  },
  responses: {
    200: {
      description: 'Success.',
      content: {
        'application/json': {
          schema: JsonSuccessBaseSchema.and(
            z
              .strictObject({
                result: z.any().exactOptional(),
                msg: z.any().exactOptional(),
                ignored_parameters_unsupported: z.any().exactOptional(),
                uri: z
                  .string()
                  .exactOptional()
                  .openapi({
                    deprecated: true,
                    description:
                      'The URL of the uploaded file. Alias of `url`.\n\n**Changes**: Deprecated in Zulip 9.0 (feature level 272). The term\n"URI" is deprecated in [web standards](https://url.spec.whatwg.org/#goals).\n',
                  }),
                url: z
                  .string()
                  .exactOptional()
                  .openapi({
                    description:
                      'The URL of the uploaded file.\n\n**Changes**: New in Zulip 9.0 (feature level 272). Previously,\nthis property was only available under the legacy `uri` name.\n',
                  }),
                filename: z
                  .string()
                  .exactOptional()
                  .openapi({
                    description:
                      'The filename that Zulip stored the upload as. This usually\ndiffers from the basename of the URL when HTML escaping is\nrequired to generate a valid URL.\n\nClients generating a Markdown link to a newly uploaded file\nshould do so by combining the `url` and `filename` fields in the\nresponse as follows: `[{filename}]({url})`, with care taken to\nclean `filename` of `[` and `]` characters that might break\nMarkdown rendering.\n\n**Changes**: New in Zulip 10.0 (feature level 285).\n',
                  }),
              })
              .openapi({
                example: {
                  msg: '',
                  result: 'success',
                  uri: '/user_uploads/1/4e/m2A3MSqFnWRLUf9SaPzQ0Up_/zulip.txt',
                  url: '/user_uploads/1/4e/m2A3MSqFnWRLUf9SaPzQ0Up_/zulip.txt',
                  filename: 'zulip.txt',
                },
                required: [],
              }),
          ),
        },
      },
    },
  },
})

export const getThumbnailStatusRealmIdStrFilenameRoute = createRoute({
  method: 'get',
  path: '/thumbnail/status/{realm_id_str}/{filename}',
  tags: ['messages'],
  summary: 'Check thumbnail status',
  description:
    'Check whether a thumbnail exists for a specific file uploaded by a user.\nThis endpoint is intended to be polled by clients to determine when\nthumbnail generation is complete.\n\n**Changes**: New in Zulip 12.0 (feature level 479).\n',
  operationId: 'check-thumbnail-status',
  request: {
    params: z.object({
      realm_id_str: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .openapi({
          param: {
            name: 'realm_id_str',
            in: 'path',
            description:
              "The realm ID component of the file's `path_id`. If the `path_id` is\n`1/4e/m2A3MSqFnWRLUf9SaPzQ0Up_/zulip.txt`, the `realm_id_str` would be `1`.\n",
            schema: { type: 'integer' },
            example: 1,
            required: true,
          },
        }),
      filename: z
        .string()
        .openapi({
          param: {
            name: 'filename',
            in: 'path',
            description:
              "The file path component of the file's `path_id` (everything\nafter the first `/`). If the `path_id` is\n`1/4e/m2A3MSqFnWRLUf9SaPzQ0Up_/zulip.txt`, the `filename`\nwould be `4e/m2A3MSqFnWRLUf9SaPzQ0Up_/zulip.txt`.\n",
            schema: { type: 'string' },
            example: '4e/m2A3MSqFnWRLUf9SaPzQ0Up_/zulip.txt',
            required: true,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Success.',
      content: {
        'application/json': {
          schema: JsonSuccessBaseSchema.and(
            z
              .strictObject({
                result: z.any().exactOptional(),
                msg: z.any().exactOptional(),
                ignored_parameters_unsupported: z.any().exactOptional(),
                has_thumbnail: z
                  .boolean()
                  .openapi({ description: 'A boolean indicating whether the thumbnail exists.\n' }),
              })
              .openapi({
                required: ['has_thumbnail'],
                example: { msg: '', result: 'success', has_thumbnail: true },
              }),
          ),
        },
      },
    },
  },
})

export const getUserUploadsRealmIdStrFilenameRoute = createRoute({
  method: 'get',
  path: '/user_uploads/{realm_id_str}/{filename}',
  tags: ['messages'],
  summary: 'Get public temporary URL for an uploaded file',
  description:
    "Get a temporary URL for access to an [uploaded file](/api/upload-file)\nthat doesn't require authentication.\n\nThe `SIGNED_ACCESS_TOKEN_VALIDITY_IN_SECONDS` server setting controls\nthe valid length of time for temporary access, which generally is set\nto a default of 60 seconds. Consumers of this API are expected to\nimmediately request the URL that it returns, and should not store it\nin any way.\n\n**Changes**: New in Zulip 3.0 (feature level 1).\n",
  operationId: 'get-file-temporary-url',
  request: {
    params: z.object({
      realm_id_str: z
        .preprocess(
          (val) =>
            typeof val === 'string' &&
            /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
            (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
              ? Number(val)
              : val,
          z.int(),
        )
        .openapi({
          param: {
            name: 'realm_id_str',
            in: 'path',
            description:
              "The realm ID component of the file's `path_id`. If the `path_id` is\n`1/4e/m2A3MSqFnWRLUf9SaPzQ0Up_/zulip.txt`, the `realm_id_str` would be `1`.\n",
            schema: { type: 'integer' },
            example: 1,
            required: true,
          },
        }),
      filename: z
        .string()
        .openapi({
          param: {
            name: 'filename',
            in: 'path',
            description:
              "The file path component of the file's `path_id` (everything\nafter the first `/`). If the `path_id` is\n`1/4e/m2A3MSqFnWRLUf9SaPzQ0Up_/zulip.txt`, the `filename`\nwould be `4e/m2A3MSqFnWRLUf9SaPzQ0Up_/zulip.txt`.\n",
            schema: { type: 'string' },
            example: '4e/m2A3MSqFnWRLUf9SaPzQ0Up_/zulip.txt',
            required: true,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Success.',
      content: {
        'application/json': {
          schema: JsonSuccessBaseSchema.and(
            z
              .strictObject({
                result: z.any().exactOptional(),
                msg: z.any().exactOptional(),
                ignored_parameters_unsupported: z.any().exactOptional(),
                url: z
                  .string()
                  .exactOptional()
                  .openapi({
                    description:
                      "A temporary URL that can be used to access the uploaded file\nwithout Zulip's normal API authentication.\n",
                  }),
              })
              .openapi({
                example: {
                  msg: '',
                  result: 'success',
                  url: '/user_uploads/temporary/322F32632F39765378464E4C63306D3961396F4970705A4D74424565432F7A756C69702E7478743A316A5053616A3A3938625F44393446466D37357254315F4F414C425A4553464F6A55',
                },
                required: [],
              }),
          ),
        },
      },
    },
  },
})

export const getUsersRoute = createRoute({
  method: 'get',
  path: '/users',
  tags: ['users'],
  summary: 'Get users',
  description:
    'Retrieve details on users in the organization.\n\nBy default, returns all accessible users in the organization.\nThe `user_ids` query parameter can be used to limit the\nresults to a specific set of user IDs.\n\nOptionally includes values of [custom profile fields](/help/custom-profile-fields).\n\nYou can also [fetch details on a single user](/api/get-user).\n\n**Changes**: In Zulip 12.0 (feature level 437), fixed a bug\ndating to feature level 232, which caused guest users to\nreceive fake backwards-compatibility users in the format\nintended for clients using `POST /register` without the\n`user_list_incomplete` client capability.\n\nThis endpoint did not support unauthenticated\naccess in organizations using the [public access\noption](/help/public-access-option) prior to Zulip 11.0\n(feature level 387).\n',
  operationId: 'get-users',
  request: {
    query: z.object({
      client_gravatar: ClientGravatarParamsSchema,
      include_custom_profile_fields: IncludeCustomProfileFieldsParamsSchema,
      user_ids: z
        .preprocess((val) => {
          if (typeof val !== 'string') return val
          try {
            return JSON.parse(val)
          } catch {
            return val
          }
        }, z.array(z.int()))
        .exactOptional()
        .openapi({
          param: {
            name: 'user_ids',
            in: 'query',
            content: {
              'application/json': {
                schema: { type: 'array', items: { type: 'integer' } },
                example: [1, 2, 3],
              },
            },
            required: false,
            description:
              'Limits the results to the specified user IDs. If not\nprovided, the server will return all accessible users in\nthe organization.\n\n**Changes**: New in Zulip 11.0 (feature level 384).\n',
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Success.',
      content: {
        'application/json': {
          schema: JsonSuccessBaseSchema.and(
            z
              .strictObject({
                result: z.any().exactOptional(),
                msg: z.any().exactOptional(),
                ignored_parameters_unsupported: z.any().exactOptional(),
                members: z
                  .array(UserSchema)
                  .exactOptional()
                  .openapi({
                    description:
                      'A list of `user` objects, each containing details about a user in the\norganization.\n',
                  }),
              })
              .openapi({
                example: {
                  msg: '',
                  result: 'success',
                  members: [
                    {
                      is_active: true,
                      email: 'AARON@zulip.com',
                      delivery_email: null,
                      is_admin: false,
                      is_owner: false,
                      role: 400,
                      avatar_url:
                        'https://secure.gravatar.com/avatar/818c212b9f8830dfef491b3f7da99a14?d=identicon&version=1',
                      bot_type: null,
                      timezone: '',
                      is_bot: false,
                      user_id: 7,
                      profile_data: {},
                      is_guest: false,
                      date_joined: '2019-10-20T07:50:53.728864+00:00',
                      full_name: 'aaron',
                      is_imported_stub: false,
                    },
                    {
                      date_joined: '2019-10-20T07:50:53.729659+00:00',
                      full_name: 'King Hamlet',
                      is_guest: false,
                      profile_data: {
                        '1': {
                          value: '+0-11-23-456-7890',
                          rendered_value: '<p>+0-11-23-456-7890</p>',
                        },
                        '2': {
                          value:
                            'I am:\n* The prince of Denmark\n* Nephew to the usurping Claudius',
                          rendered_value:
                            '<p>I am:</p>\n<ul>\n<li>The prince of Denmark</li>\n<li>Nephew to the usurping Claudius</li>\n</ul>',
                        },
                        '3': { rendered_value: '<p>Dark chocolate</p>', value: 'Dark chocolate' },
                        '4': { value: '0' },
                        '5': { value: '1900-01-01' },
                        '6': { value: 'https://blog.zulig.org' },
                        '7': { value: '[11]' },
                        '8': { value: 'zulipbot' },
                      },
                      user_id: 10,
                      is_bot: false,
                      bot_type: null,
                      timezone: '',
                      is_admin: false,
                      is_owner: false,
                      role: 400,
                      avatar_url:
                        'https://secure.gravatar.com/avatar/6d8cad0fd00256e7b40691d27ddfd466?d=identicon&version=1',
                      is_active: true,
                      email: 'hamlet@zulip.com',
                      delivery_email: null,
                      is_imported_stub: false,
                    },
                    {
                      bot_owner_id: 11,
                      is_guest: false,
                      date_joined: '2019-10-20T12:52:17.862053+00:00',
                      full_name: "Iago's Bot",
                      email: 'iago-bot@zulipdev.com',
                      delivery_email: 'iago-bot@zulipdev.com',
                      is_active: true,
                      avatar_url:
                        'https://secure.gravatar.com/avatar/7328586831cdbb1627649bd857b1ee8c?d=identicon&version=1',
                      is_admin: false,
                      is_owner: false,
                      role: 400,
                      user_id: 23,
                      bot_type: 1,
                      timezone: '',
                      is_bot: true,
                      is_imported_stub: false,
                    },
                  ],
                },
                required: [],
              }),
          ),
        },
      },
    },
  },
})

export const postUsersRoute = createRoute({
  method: 'post',
  path: '/users',
  tags: ['users'],
  summary: 'Create a user',
  description:
    'Create a new user account via the API.\n\n!!! warn ""\n\n    **Note**: On Zulip Cloud, this feature is available only for\n    organizations on a [Zulip Cloud Standard](https://zulip.com/plans/)\n    or [Zulip Cloud Plus](https://zulip.com/plans/) plan. Administrators\n    can request the required `can_create_users` permission for a bot or\n    user by contacting [Zulip Cloud support][support] with an\n    explanation for why it is needed. Self-hosted installations can\n    toggle `can_create_users` on an account using the `manage.py\n    change_user_role` [management command][management-commands].\n\n**Changes**: Before Zulip 4.0 (feature level 36), this endpoint was\navailable to all organization administrators.\n\n[support]: /help/contact-support\n[management-commands]: https://zulip.readthedocs.io/en/latest/production/management-commands.html\n',
  operationId: 'create-user',
  request: {
    body: {
      content: {
        'application/x-www-form-urlencoded': {
          schema: z
            .object({
              email: z
                .string()
                .openapi({
                  description: 'The email address of the new user.\n',
                  example: 'username@example.com',
                }),
              password: z
                .string()
                .openapi({ description: 'The password of the new user.\n', example: 'abcd1234' }),
              full_name: z
                .string()
                .openapi({ description: 'The full name of the new user.\n', example: 'New User' }),
            })
            .openapi({ required: ['email', 'password', 'full_name'] }),
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Success.',
      content: {
        'application/json': {
          schema: JsonSuccessBaseSchema.and(
            z
              .strictObject({
                result: z.any().exactOptional(),
                msg: z.any().exactOptional(),
                ignored_parameters_unsupported: z.any().exactOptional(),
                user_id: z
                  .int()
                  .exactOptional()
                  .openapi({
                    description:
                      'The ID assigned to the newly created user.\n\n**Changes**: New in Zulip 4.0 (feature level 30).\n',
                  }),
              })
              .openapi({ example: { msg: '', result: 'success', user_id: 25 }, required: [] }),
          ),
        },
      },
    },
    400: {
      description: 'Bad request.',
      content: {
        'application/json': {
          schema: CodedErrorSchema.and(
            z
              .any()
              .openapi({
                example: { code: 'BAD_REQUEST', msg: 'Email is already in use.', result: 'error' },
                description:
                  'A typical JSON response for when another user with the same\nemail address already exists in the realm:\n',
              }),
          ),
        },
      },
    },
  },
})

