export const postUsersMeAlertWordsRoute = createRoute({
  method: 'post',
  path: '/users/me/alert_words',
  tags: ['users'],
  summary: 'Add alert words',
  description:
    "Add words (or phrases) to the user's set of configured [alert words][alert-words].\n\n[alert-words]: /help/dm-mention-alert-notifications#alert-words\n",
  operationId: 'add-alert-words',
  request: {
    body: {
      content: {
        'application/x-www-form-urlencoded': {
          schema: z
            .object({
              alert_words: z
                .preprocess(
                  (val) => (val === undefined || Array.isArray(val) ? val : [val]),
                  z.array(z.string()),
                )
                .openapi({
                  description:
                    "An array of strings to be added to the user's set of configured\nalert words. Strings already present in the user's set of alert words\nalready are ignored.\n\nAlert words are case insensitive.\n",
                  example: ['foo', 'bar'],
                }),
            })
            .openapi({ required: ['alert_words'] }),
          encoding: { alert_words: { contentType: 'application/json' } },
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Success.',
      content: {
        'application/json': {
          schema: JsonSuccessBaseSchema.and(
            z
              .strictObject({
                result: z.any().exactOptional(),
                msg: z.any().exactOptional(),
                ignored_parameters_unsupported: z.any().exactOptional(),
                alert_words: z
                  .array(z.string())
                  .exactOptional()
                  .openapi({
                    description:
                      'An array of strings, where each string is an alert word (or phrase)\nconfigured by the user.\n',
                  }),
              })
              .openapi({
                example: {
                  result: 'success',
                  msg: '',
                  alert_words: ['foo', 'bar', 'natural', 'illustrious'],
                },
                required: [],
              }),
          ),
        },
      },
    },
    400: {
      description: 'Bad request.',
      content: {
        'application/json': {
          schema: CodedErrorSchema.and(
            z
              .any()
              .openapi({
                example: {
                  code: 'BAD_REQUEST',
                  msg: 'alert_words[0] is too long (limit: 100 characters)',
                  result: 'error',
                },
                description:
                  'An example JSON response for when a supplied alert word (or phrase)\nexceeds the character limit:\n',
              }),
          ),
        },
      },
    },
  },
})

