            principals: { contentType: 'application/json' },
            authorization_errors_fatal: { contentType: 'application/json' },
            announce: { contentType: 'application/json' },
            invite_only: { contentType: 'application/json' },
            is_web_public: { contentType: 'application/json' },
            is_default_stream: { contentType: 'application/json' },
            history_public_to_subscribers: { contentType: 'application/json' },
            default_push_notifications: { contentType: 'application/json' },
            topics_policy: { contentType: 'application/json' },
            can_add_subscribers_group: { contentType: 'application/json' },
            can_remove_subscribers_group: { contentType: 'application/json' },
            can_administer_channel_group: { contentType: 'application/json' },
            can_delete_any_message_group: { contentType: 'application/json' },
            can_delete_own_message_group: { contentType: 'application/json' },
            can_move_messages_out_of_channel_group: { contentType: 'application/json' },
            can_move_messages_within_channel_group: { contentType: 'application/json' },
            can_send_message_group: { contentType: 'application/json' },
            can_subscribe_group: { contentType: 'application/json' },
            can_resolve_topics_group: { contentType: 'application/json' },
