export const deleteUsersMeApnsDeviceTokenRoute = createRoute({
  method: 'delete',
  path: '/users/me/apns_device_token',
  tags: ['users'],
  summary: 'Remove an APNs device token',
  description:
    'This endpoint removes an APNs device token for iOS push notifications.\n\n**Changes**: Deprecated in Zulip 11.0 (feature level 406) and will be\nremoved in a future release. Clients connecting to newer servers and\nwith E2EE push notifications support should delete the account record\nin their local accounts table that corresponds to the `push_account_id`\nsupplied when registering via the [Register E2EE push device](/api/register-push-device)\nendpoint, to stop displaying notifications for that registration.\n',
  operationId: 'remove-apns-token',
  request: {
    body: {
      content: {
        'application/x-www-form-urlencoded': {
          schema: z
            .object({
              token: z
                .string()
                .openapi({ description: 'The token provided by the device.\n', example: 'c0ffee' }),
            })
            .openapi({ required: ['token'] }),
        },
      },
      required: true,
    },
  },
  responses: {
    200: SimpleSuccessResponse,
    400: {
      description: 'Bad request.',
      content: {
        'application/json': {
          schema: z.xor([
            CodedErrorSchema.and(
              z
                .any()
                .openapi({
                  description:
                    "A typical failed JSON response for when the token's length is invalid\nor it is empty:\n",
                  example: {
                    result: 'error',
                    msg: 'Empty or invalid length token',
                    code: 'BAD_REQUEST',
                  },
                }),
            ),
            CodedErrorSchema.and(
              z
                .any()
                .openapi({
                  example: { result: 'error', msg: 'Token does not exist', code: 'BAD_REQUEST' },
                  description:
                    'A typical failed JSON response for when the token does not exist:\n',
                }),
            ),
          ]),
        },
      },
    },
  },
  deprecated: true,
})

