export const getUsersUserIdSubscriptionsStreamIdRoute = createRoute({
  method: 'get',
  path: '/users/{user_id}/subscriptions/{stream_id}',
  tags: ['channels'],
  summary: 'Get subscription status',
  description:
    'Check whether a user is subscribed to a channel.\n\n**Changes**: Prior to Zulip 12.0 (feature level 458), this endpoint\ndid not support querying subscriptions of bot users.\n\nNew in Zulip 3.0 (feature level 12).\n',
  operationId: 'get-subscription-status',
  request: {
    params: z.object({ user_id: UserIdParamsSchema, stream_id: ChannelIdInPathParamsSchema }),
  },
  responses: {
    200: {
      description: 'Success',
      content: {
        'application/json': {
          schema: JsonSuccessBaseSchema.and(
            z
              .strictObject({
                result: z.any().exactOptional(),
                msg: z.any().exactOptional(),
                ignored_parameters_unsupported: z.any().exactOptional(),
                is_subscribed: z
                  .boolean()
                  .exactOptional()
                  .openapi({ description: 'Whether the user is subscribed to the channel.\n' }),
              })
              .openapi({
                example: { msg: '', result: 'success', is_subscribed: false },
                required: [],
              }),
          ),
        },
      },
    },
  },
})

export const getUsersUserIdChannelsRoute = createRoute({
  method: 'get',
  path: '/users/{user_id}/channels',
  tags: ['channels'],
  summary: "Get a user's subscribed channels",
  description:
    'Gets the list of channels that the target user is subscribed to.\n\nThe [channel security model](/help/channel-permissions) means only those\nsubscribed channels to which the acting user has metadata access are\nreturned.\n\nFor organization administrators, this is guaranteed to be all channels\nthe target user is subscribed to, since organization administrators\nimplicitly have metadata access to all channels.\n\n**Changes**: Prior to Zulip 12.0 (feature level 458), target users that\nwere bots resulted in a permissions error.\n\nNew in Zulip 12.0 (feature level 440).\n',
  operationId: 'get-user-channels',
  request: { params: z.object({ user_id: UserIdParamsSchema }) },
  responses: {
    200: {
      description: 'Success',
      content: {
        'application/json': {
          schema: JsonSuccessBaseSchema.and(
            z
              .strictObject({
                result: z.any().exactOptional(),
                msg: z.any().exactOptional(),
                ignored_parameters_unsupported: z.any().exactOptional(),
                subscribed_channel_ids: z
                  .array(z.int())
                  .exactOptional()
                  .openapi({
                    description:
                      "IDs of the channels that the target user is subscribed to\n(limited by the acting user's permissions to view subscribers).\n",
                  }),
              })
              .openapi({
                example: { msg: '', result: 'success', subscribed_channel_ids: [3, 5, 10] },
                required: [],
              }),
          ),
        },
      },
    },
  },
})

export const postRealmEmojiEmojiNameRoute = createRoute({
  method: 'post',
  path: '/realm/emoji/{emoji_name}',
  tags: ['server_and_organizations'],
  summary: 'Upload custom emoji',
  description:
    "This endpoint is used to upload a custom emoji for use in the user's\norganization. Access to this endpoint depends on the\n[organization's configuration](https://zulip.com/help/custom-emoji#change-who-can-add-custom-emoji).\n",
  operationId: 'upload-custom-emoji',
  request: {
    params: z.object({
      emoji_name: z
        .string()
        .openapi({
          param: {
            name: 'emoji_name',
            required: true,
            in: 'path',
            description:
              'The name that should be associated with the uploaded emoji image/gif.\nThe emoji name can only contain letters, numbers, dashes, and spaces.\nUpper and lower case letters are treated the same, and underscores (\\_)\nare treated the same as spaces (consistent with how the Zulip UI\nhandles emoji).\n',
            schema: { type: 'string' },
            example: 'smile',
          },
        }),
    }),
    body: {
      content: {
        'multipart/form-data': {
          schema: z
            .object({
              filename: z
                .file()
                .exactOptional()
                .openapi({ type: 'string', format: 'binary', example: '/path/to/img.png' }),
            })
            .openapi({ required: [] }),
        },
      },
    },
  },
  responses: { 200: SimpleSuccessResponse },
})

export const deleteRealmEmojiEmojiNameRoute = createRoute({
  method: 'delete',
  path: '/realm/emoji/{emoji_name}',
  tags: ['server_and_organizations'],
  summary: 'Deactivate custom emoji',
  description:
    "[Deactivate a custom emoji](/help/custom-emoji#deactivate-custom-emoji) from\nthe user's organization.\n\nUsers can only deactivate custom emoji that they added themselves except for\norganization administrators, who can deactivate any custom emoji.\n\nNote that deactivated emoji will still be visible in old messages, reactions,\nuser statuses and channel descriptions.\n\n**Changes**: Before Zulip 8.0 (feature level 190), this endpoint returned an\nHTTP status code of 400 when the emoji did not exist, instead of 404.\n",
  operationId: 'deactivate-custom-emoji',
  request: {
    params: z.object({
      emoji_name: z
        .string()
        .openapi({
          param: {
            name: 'emoji_name',
            required: true,
            in: 'path',
            description: 'The name of the custom emoji to deactivate.\n',
            schema: { type: 'string' },
            example: 'green_tick',
          },
        }),
    }),
  },
  responses: {
    200: SimpleSuccessResponse,
    404: {
      description: 'Not Found.',
      content: {
        'application/json': {
          schema: CodedErrorSchema.and(
            z
              .any()
              .openapi({
                description:
                  'An example JSON response for when no emoji exists with the provided name:\n',
                example: {
                  code: 'BAD_REQUEST',
                  result: 'error',
                  msg: "Emoji 'green_tick' does not exist",
                },
              }),
          ),
        },
      },
    },
  },
})

