export const getRealmPresenceRoute = createRoute({
  method: 'get',
  path: '/realm/presence',
  tags: ['server_and_organizations'],
  summary: 'Get presence of all users',
  description:
    'Get the presence information of all the users in an organization.\n\nIf the `CAN_ACCESS_ALL_USERS_GROUP_LIMITS_PRESENCE` server-level\nsetting is set to `true`, presence information of only accessible\nusers are returned.\n\nComplete Zulip apps are recommended to fetch presence\ninformation when they post their own state using the [`POST\n/presence`](/api/update-presence) API endpoint.\n',
  operationId: 'get-presence',
  responses: {
    200: {
      description: 'Success.',
      content: {
        'application/json': {
          schema: JsonSuccessBaseSchema.and(
            z
              .strictObject({
                result: z.any().exactOptional(),
                msg: z.any().exactOptional(),
                ignored_parameters_unsupported: z.any().exactOptional(),
                server_timestamp: z
                  .number()
                  .exactOptional()
                  .openapi({
                    description:
                      'The time when the server fetched the `presences` data included\nin the response.\n',
                  }),
                presences: z
                  .record(
                    z.string(),
                    z
                      .record(z.string(), LegacyPresenceFormatSchema)
                      .openapi({
                        description:
                          "`{user_email}`: Object containing the details of a user's presence.\nThe object's key is the user's Zulip API email.\n",
                      }),
                  )
                  .exactOptional()
                  .openapi({
                    description:
                      'A dictionary where each entry describes the presence details\nof a user in the Zulip organization.\n',
                  }),
              })
              .openapi({
                example: {
                  msg: '',
                  presences: {
                    'iago@zulip.com': {
                      website: {
                        client: 'website',
                        pushable: false,
                        status: 'active',
                        timestamp: 1656958485,
                      },
                      aggregated: { client: 'website', status: 'active', timestamp: 1656958485 },
                    },
                  },
                  result: 'success',
                  server_timestamp: 1656958539.6287155,
                },
                required: [],
              }),
          ),
        },
      },
    },
  },
})

export const getRealmDomainsRoute = createRoute({
  method: 'get',
  path: '/realm/domains',
  tags: ['server_and_organizations'],
  summary: 'Get allowed domains',
  description:
    'Get the set of allowed domains configured in the organization for user\naccount email addresses.\n\nAs each Zulip user account is associated with an email address, organization\nowners can [restrict new account creation (and email\nchanges)](/help/restrict-account-creation) to email addresses with these\ndomains.\n',
  operationId: 'get-realm-domains',
  responses: {
    200: {
      description: 'Success.',
      content: {
        'application/json': {
          schema: JsonSuccessBaseSchema.and(
            z
              .strictObject({
                result: z.any().exactOptional(),
                msg: z.any().exactOptional(),
                ignored_parameters_unsupported: z.any().exactOptional(),
                domains: z
                  .array(RealmDomainSchema)
                  .exactOptional()
                  .openapi({
                    description:
                      'A list of objects containing details of each domain allowed\nfor user account email addresses.\n',
                  }),
              })
              .openapi({
                example: {
                  result: 'success',
                  msg: '',
                  domains: [{ domain: 'example.com', allow_subdomains: false }],
                },
                required: [],
              }),
          ),
        },
      },
    },
  },
})

export const postRealmDomainsRoute = createRoute({
  method: 'post',
  path: '/realm/domains',
  tags: ['server_and_organizations'],
  summary: 'Add an allowed domain',
  description:
    'Add a domain to the set of allowed domains configured in the organization\nfor [user account email addresses](/help/restrict-account-creation).\n\n**Changes**: Prior to Zulip 6.0 (feature level 143), organization\nadministrators who were not owners could access this endpoint.\n',
  operationId: 'add-realm-domain',
  request: {
    body: {
      content: {
        'application/x-www-form-urlencoded': {
          schema: z
            .object({
              domain: z
                .string()
                .openapi({
                  description:
                    'The new domain.\n\n**Changes**: In Zulip 4.0 (feature level 63), the unnecessary\nJSON-encoding of this parameter was removed.\n',
                  example: 'example.com',
                }),
              allow_subdomains: z
                .preprocess(
                  ((read) => (val: unknown) => {
                    const result = read.safeParse(val)
                    return result.success ? result.data : val
                  })(z.stringbool()),
                  z.boolean(),
                )
                .openapi({
                  description: 'Whether subdomains are allowed for this domain.\n',
                  example: false,
                }),
            })
            .openapi({ required: ['domain', 'allow_subdomains'] }),
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Success.',
      content: {
        'application/json': {
          schema: JsonSuccessBaseSchema.and(
            z
              .strictObject({
                result: z.any().exactOptional(),
                msg: z.any().exactOptional(),
                ignored_parameters_unsupported: z.any().exactOptional(),
                new_domain: z
                  .array(z.xor([z.int(), z.string()]))
                  .exactOptional()
                  .openapi({
                    description:
                      'An array containing the ID of the newly added domain\nand the submitted domain name string.\n',
                  }),
              })
              .openapi({
                example: { result: 'success', msg: '', new_domain: [1, 'example.com'] },
                required: [],
              }),
          ),
        },
      },
    },
  },
})

