export const postRealmDeactivateRoute = createRoute({
  method: 'post',
  path: '/realm/deactivate',
  tags: ['server_and_organizations'],
  summary: 'Deactivate an organization',
  description:
    '[Deactivate an organization](/help/deactivate-your-organization) on the\nZulip server. Deactivating an organization immediately logs out all of\nits users and prevents them from logging in again.\n\nA deactivated organization can be reactivated via a [management\ncommand](https://zulip.readthedocs.io/en/latest/production/management-commands.html),\nunless its data has been permanently deleted (see the\n[`deletion_delay_days` parameter](/api/deactivate-realm#parameter-deletion_delay_days)\nbelow).\n\nThis endpoint is primarily useful for Zulip servers that host\n[multiple organizations](https://zulip.readthedocs.io/en/latest/production/multiple-organizations.html).\n',
  operationId: 'deactivate-realm',
  request: {
    body: {
      content: {
        'application/x-www-form-urlencoded': {
          schema: z
            .strictObject({
              deletion_delay_days: z
                .preprocess(
                  (val) => (val === 'null' ? null : val),
                  z
                    .preprocess(
                      (val) =>
                        typeof val === 'string' &&
                        /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                        (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                          ? Number(val)
                          : val,
                      z.int(),
                    )
                    .nullable(),
                )
                .exactOptional()
                .openapi({
                  description:
                    "The number of days to wait before permanently deleting all\nof the deactivated organization's data (users, channels,\nmessages, etc.).\n\nA value of `0` will delete the organization's data\nimmediately, which means that the organization cannot be\nreactivated. A `null` value indicates that the organization's\ndata will not be deleted, but rather retained indefinitely.\n\nValid values for this parameter are limited to the range\npermitted by the server, indicated by the\n`server_min_deactivated_realm_deletion_days` and\n`server_max_deactivated_realm_deletion_days` fields in the\n[`POST /register`](/api/register-queue) response. A value of\n`null` is only permitted when\n`server_max_deactivated_realm_deletion_days` is `null`. A\nvalue of `0` is only permitted when\n`server_min_deactivated_realm_deletion_days` is `null`.\n\nThese limits do not apply to\n[Zulip Cloud demo organizations](/help/demo-organizations),\nfor which this parameter is instead required: it must be `0`\nwhen the organization owner has not configured an email\naddress, and otherwise must not exceed the number of days\nremaining before the demo organization's scheduled deletion.\n\n**Changes**: New in Zulip 10.0 (feature level 332).\n",
                  example: 30,
                }),
            })
            .openapi({ required: [] }),
          encoding: { deletion_delay_days: { contentType: 'application/json' } },
        },
      },
    },
  },
  responses: {
    200: SimpleSuccessResponse,
    400: {
      description: 'Bad request.',
      content: {
        'application/json': {
          schema: z.xor([
            CodedErrorSchema.and(
              z
                .any()
                .openapi({
                  description:
                    'An example JSON response for when the current user is\nnot an organization owner:\n',
                  example: {
                    code: 'UNAUTHORIZED_PRINCIPAL',
                    msg: 'Must be an organization owner',
                    result: 'error',
                  },
                }),
            ),
            CodedErrorSchema.and(
              z
                .any()
                .openapi({
                  description:
                    'An example JSON response for when `deletion_delay_days`\nis below the minimum permitted by the server:\n',
                  example: {
                    code: 'BAD_REQUEST',
                    msg: 'Data deletion time must be at least 14 days in the future.',
                    result: 'error',
                  },
                }),
            ),
            CodedErrorSchema.and(
              z
                .any()
                .openapi({
                  description:
                    'An example JSON response for when `deletion_delay_days`\nexceeds the maximum permitted by the server:\n',
                  example: {
                    code: 'BAD_REQUEST',
                    msg: 'Data deletion time must be at most 30 days in the future.',
                    result: 'error',
                  },
                }),
            ),
            CodedErrorSchema.and(
              z
                .any()
                .openapi({
                  description:
                    'An example JSON response for when an invalid\n`deletion_delay_days` is given for a\n[Zulip Cloud demo organization](/help/demo-organizations):\n',
                  example: {
                    code: 'BAD_REQUEST',
                    msg: 'Invalid data deletion time for demo organization.',
                    result: 'error',
                  },
                }),
            ),
          ]),
        },
      },
    },
  },
})

