export const getRealmLinkifiersRoute = createRoute({
  method: 'get',
  path: '/realm/linkifiers',
  tags: ['server_and_organizations'],
  summary: 'Get linkifiers',
  description:
    "List all of an organization's configured\n[linkifiers](/help/add-a-custom-linkifier), regular\nexpression patterns that are automatically linkified when they appear\nin messages and topics.\n\n**Changes**: New in Zulip 4.0 (feature level 54). On older versions,\na similar `GET /realm/filters` endpoint was available with each entry in\na `[pattern, url_format, id]` tuple format.\n",
  operationId: 'get-linkifiers',
  responses: {
    200: {
      description: 'Success.',
      content: {
        'application/json': {
          schema: JsonSuccessBaseSchema.and(
            z
              .strictObject({
                result: z.any().exactOptional(),
                msg: z.any().exactOptional(),
                ignored_parameters_unsupported: z.any().exactOptional(),
                linkifiers: z
                  .array(
                    z
                      .strictObject({
                        pattern: z
                          .string()
                          .exactOptional()
                          .openapi({
                            description:
                              'The string regex pattern which represents the pattern that\nshould be linkified by this linkifier.\n',
                          }),
                        url_template: z
                          .string()
                          .exactOptional()
                          .openapi({
                            description:
                              'The [RFC 6570](https://www.rfc-editor.org/rfc/rfc6570.html) compliant\nURL template to be used for linkifying matches.\n\n**Changes**: New in Zulip 7.0 (feature level 176). This replaced `url_format`,\nwhich contained a URL format string.\n',
                          }),
                        id: z
                          .int()
                          .exactOptional()
                          .openapi({ description: 'The ID of the linkifier.\n' }),
                        example_input: z
                          .string()
                          .nullable()
                          .exactOptional()
                          .openapi({
                            description:
                              "An example input string that matches the linkifier's pattern.\nThis is required for reverse linkifiers.\n\n**Changes**: New in Zulip 12.0 (feature level 471).\n",
                          }),
                        reverse_template: z
                          .string()
                          .nullable()
                          .exactOptional()
                          .openapi({
                            description:
                              'A simple template using `{variable}` for variables that can\nbe used to generate the Markdown linkifier syntax, given a\nURL matching the URL template.\n\n`{{ "{{/}}" }}` can be used for literal `{/}` characters.\n\n**Changes**: New in Zulip 12.0 (feature level 471).\n',
                          }),
                        alternative_url_templates: z
                          .array(z.string())
                          .exactOptional()
                          .openapi({
                            description:
                              'An array of additional [RFC 6570][rfc6570] compliant URL\ntemplate strings that are used for reverse linkification\n(converting pasted URLs to linkifier pattern text). These\ntemplates have no effect on forward linkification.\n\n[rfc6570]: https://www.rfc-editor.org/rfc/rfc6570.html\n\n**Changes**: New in Zulip 12.0 (feature level e2b257).\n',
                          }),
                      })
                      .openapi({ required: [] }),
                  )
                  .exactOptional()
                  .openapi({
                    description:
                      'An ordered array of objects, where each object\ndescribes a linkifier.\n\nClients should always process linkifiers in the order given;\nthis is important if the realm has linkifiers with overlapping\npatterns. The order can be modified using [`PATCH\n/realm/linkifiers`](/api/reorder-linkifiers).\n',
                  }),
              })
              .openapi({
                example: {
                  msg: '',
                  linkifiers: [
                    {
                      pattern: '#(?P<id>[0-9]+)',
                      url_template: 'https://github.com/zulip/zulip/issues/{id}',
                      id: 1,
                      example_input: '#1234',
                      reverse_template: '#{id}',
                      alternative_url_templates: ['https://github.com/zulip/zulip/pull/{id}'],
                    },
                  ],
                  result: 'success',
                },
                required: [],
              }),
          ),
        },
      },
    },
  },
})

export const patchRealmLinkifiersRoute = createRoute({
  method: 'patch',
  path: '/realm/linkifiers',
  tags: ['server_and_organizations'],
  summary: 'Reorder linkifiers',
  description:
    "Change the order that the regular expression patterns in the organization's\n[linkifiers](/help/add-a-custom-linkifier) are matched in messages and topics.\nUseful when defining linkifiers with overlapping patterns.\n\n**Changes**: New in Zulip 8.0 (feature level 202). Before this feature level,\nlinkifiers were always processed in order by ID, which meant users would\nneed to delete and recreate them to reorder the list of linkifiers.\n",
  operationId: 'reorder-linkifiers',
  request: {
    body: {
      content: {
        'application/x-www-form-urlencoded': {
          schema: z
            .object({
              ordered_linkifier_ids: z
                .preprocess(
                  (val) => (val === undefined || Array.isArray(val) ? val : [val]),
                  z.array(
                    z.preprocess(
                      (val) =>
                        typeof val === 'string' &&
                        /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                        (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                          ? Number(val)
                          : val,
                      z.int(),
                    ),
                  ),
                )
                .openapi({
                  description:
                    'A list of the IDs of all the linkifiers defined in this\norganization, in the desired new order.\n',
                  example: [3, 2, 1, 5],
                }),
            })
            .openapi({ required: ['ordered_linkifier_ids'] }),
          encoding: { ordered_linkifier_ids: { contentType: 'application/json' } },
        },
      },
      required: true,
    },
  },
  responses: { 200: SimpleSuccessResponse },
})

export const postRealmFiltersRoute = createRoute({
  method: 'post',
  path: '/realm/filters',
  tags: ['server_and_organizations'],
  summary: 'Add a linkifier',
  description:
    'Configure [linkifiers](/help/add-a-custom-linkifier),\nregular expression patterns that are automatically linkified when they\nappear in messages and topics.\n',
  operationId: 'add-linkifier',
  request: {
    body: {
      content: {
        'application/x-www-form-urlencoded': {
          schema: z
            .object({
              pattern: LinkifierPatternSchema,
              url_template: LinkifierURLTemplateSchema,
              example_input: z
                .string()
                .nullable()
                .exactOptional()
                .openapi({
                  example: '#1234',
                  description:
                    "An example input string that matches the linkifier's pattern.\nThis is required for reverse linkifiers.\n\n**Changes**: New in Zulip 12.0 (feature level 471).\n",
                }),
              reverse_template: z
                .string()
                .nullable()
                .exactOptional()
                .openapi({
                  example: '#{id}',
                  description:
                    'A simple template using `{variable}` for variables that can\nbe used to generate the Markdown linkifier syntax, given a\nURL matching the URL template.\n\n`{{ "{{/}}" }}` can be used for literal `{/}` characters.\n\nServer verifies that variables extracted from example_input using\nurl_pattern when passed to reverse_template returns example_input\nback to us.\n\n**Changes**: New in Zulip 12.0 (feature level 471).\n',
                }),
              alternative_url_templates: z
                .preprocess(
                  (val) => (val === undefined || Array.isArray(val) ? val : [val]),
                  z.array(z.string()),
                )
                .exactOptional()
                .openapi({
                  example: ['https://github.com/zulip/zulip/pull/{id}'],
                  description:
                    'An array of additional [RFC 6570][rfc6570] compliant URL\ntemplate strings that are used for reverse linkification\n(converting pasted URLs to linkifier pattern text). These\ntemplates have no effect on forward linkification.\n\n[rfc6570]: https://www.rfc-editor.org/rfc/rfc6570.html\n\n**Changes**: New in Zulip 12.0 (feature level e2b257).\n',
                }),
            })
            .openapi({ required: ['pattern', 'url_template'] }),
          encoding: { alternative_url_templates: { contentType: 'application/json' } },
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Success.',
      content: {
        'application/json': {
          schema: JsonSuccessBaseSchema.and(
            z
              .strictObject({
                result: z.any().exactOptional(),
                msg: z.any().exactOptional(),
                ignored_parameters_unsupported: z.any().exactOptional(),
                id: z
                  .int()
                  .exactOptional()
                  .openapi({ description: 'The numeric ID assigned to this filter.\n' }),
              })
              .openapi({ example: { id: 42, result: 'success', msg: '' }, required: [] }),
          ),
        },
      },
    },
  },
})

