export const postInvitesRoute = createRoute({
  method: 'post',
  path: '/invites',
  tags: ['invites'],
  summary: 'Send invitations',
  description:
    'Send [invitations](/help/invite-new-users) to specified email addresses.\n\n**Changes**: In Zulip 6.0 (feature level 126), the `invite_expires_in_days`\nparameter was removed and replaced by `invite_expires_in_minutes`.\n\nIn Zulip 5.0 (feature level 117), added support for passing `null` as\nthe `invite_expires_in_days` parameter to request an invitation that never\nexpires.\n\nIn Zulip 5.0 (feature level 96), the `invite_expires_in_days` parameter was\nadded which specified the number of days before the invitation would expire.\n',
  operationId: 'send-invites',
  request: {
    body: {
      content: {
        'application/x-www-form-urlencoded': {
          schema: z
            .object({
              invitee_emails: z
                .string()
                .openapi({
                  description:
                    'The string containing the email addresses, separated by commas or\nnewlines, that will be sent an invitation.\n',
                  example: 'example@zulip.com, logan@zulip.com',
                }),
              invite_expires_in_minutes: z
                .preprocess(
                  (val) => (val === 'null' ? null : val),
                  z.preprocess(
                    (val) =>
                      typeof val === 'string' &&
                      /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                      (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                        ? Number(val)
                        : val,
                    InviteExpirationParameterSchema,
                  ),
                )
                .exactOptional(),
              invite_as: z
                .preprocess(
                  (val) =>
                    typeof val === 'string' &&
                    /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                    (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                      ? Number(val)
                      : val,
                  InviteRoleParameterSchema,
                )
                .exactOptional(),
              stream_ids: z
                .preprocess(
                  (val) => (val === undefined || Array.isArray(val) ? val : [val]),
                  z.array(
                    z.preprocess(
                      (val) =>
                        typeof val === 'string' &&
                        /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                        (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                          ? Number(val)
                          : val,
                      z.int(),
                    ),
                  ),
                )
                .openapi({
                  description:
                    'A list containing the [IDs of the channels](/api/get-stream-id) that the\nnewly created user will be automatically subscribed to if the invitation\nis accepted, in addition to any default channels that the new user may\nbe subscribed to based on the `include_realm_default_subscriptions`\nparameter.\n\nRequested channels must either be default channels for the\norganization, or ones the acting user has permission to add\nsubscribers to.\n\nThis list must be empty if the current user has the unlikely\nconfiguration of being able to send invitations while lacking\npermission to [subscribe other users to channels][can-subscribe-others].\n\n**Changes**: Prior to Zulip 10.0 (feature level 342), default channels\nthat the acting user did not directly have permission to add\nsubscribers to would be rejected.\n\nBefore Zulip 7.0 (feature level 180), specifying `stream_ids` as an\nempty list resulted in an error.\n\n[can-subscribe-others]: /help/configure-who-can-invite-to-channels\n',
                  example: [1, 10],
                }),
              group_ids: z
                .preprocess(
                  (val) => (val === undefined || Array.isArray(val) ? val : [val]),
                  z.array(
                    z.preprocess(
                      (val) =>
                        typeof val === 'string' &&
                        /^-?(\d+(\.\d*)?|\.\d+)([eE][+-]?\d+)?$/.test(val) &&
                        (!/^-?\d+$/.test(val) || Number.isSafeInteger(Number(val)))
                          ? Number(val)
                          : val,
                      z.int(),
                    ),
                  ),
                )
                .exactOptional()
                .openapi({
                  description:
                    'A list containing the [IDs of the user groups](/api/get-user-groups) that\nthe newly created user will be automatically added to if the invitation\nis accepted. If the list is empty, then the new user will not be\nadded to any user groups. The acting user must have permission to add users\nto the groups listed in this request.\n\n**Changes**: New in Zulip 10.0 (feature level 322).\n',
                  example: [],
                }),
              include_realm_default_subscriptions: z
                .preprocess(
                  ((read) => (val: unknown) => {
                    const result = read.safeParse(val)
                    return result.success ? result.data : val
                  })(z.stringbool()),
                  z.boolean(),
                )
                .default(false)
                .exactOptional()
                .openapi({
                  description:
                    "Boolean indicating whether the newly created user should be subscribed\nto the [default channels][default-channels] for the organization.\n\nNote that this parameter can be `true` even if the user creating the\ninvitation does not generally have permission to [subscribe other\nusers to channels][can-subscribe-others].\n\n**Changes**: New in Zulip 9.0 (feature level 261). Previous versions\nof Zulip behaved as though this parameter was always `false`; clients\nneeded to include the organization's default channels in the\n`stream_ids` parameter for a newly created user to be automatically\nsubscribed to them.\n\n[default-channels]: /help/set-default-channels-for-new-users\n[can-subscribe-others]: /help/configure-who-can-invite-to-channels\n",
                  example: false,
                }),
              notify_referrer_on_join: z
                .preprocess(
                  ((read) => (val: unknown) => {
                    const result = read.safeParse(val)
                    return result.success ? result.data : val
                  })(z.stringbool()),
                  z.boolean(),
                )
                .default(true)
                .exactOptional()
                .openapi({
                  description:
                    'A boolean indicating whether the referrer would like to receive a\ndirect message from [notification\nbot](/help/configure-automated-notices) when a user account is created\nusing this invitation.\n\n**Changes**: New in Zulip 9.0 (feature level 267). Previously,\nreferrers always received such direct messages.\n',
                  example: false,
                }),
              welcome_message_custom_text: z
                .string()
                .nullable()
                .exactOptional()
                .openapi({
                  description:
                    "Custom message text, in Zulip Markdown format, to be sent by the\nWelcome Bot to new users that join the organization via this\ninvitation.\n\nMaximum length is 8000 Unicode code points.\n\nOnly organization administrators can use this feature; for other\nusers, the value is always `null`.\n\n- `null`: the organization's default `welcome_message_custom_text` is used.\n- Empty string: no Welcome Bot custom message is sent.\n- Otherwise, the provided string is the custom message.\n\n**Changes**: New in Zulip 11.0 (feature level 416).\n",
                  example: "Welcome to Zulip! We're excited to have you on board.",
                }),
            })
            .openapi({ required: ['invitee_emails', 'stream_ids'] }),
          encoding: {
            invite_expires_in_minutes: { contentType: 'application/json' },
            stream_ids: { contentType: 'application/json' },
            group_ids: { contentType: 'application/json' },
          },
        },
      },
      required: true,
    },
  },
  responses: {
    200: {
      description: 'Success.',
      content: {
        'application/json': {
          schema: JsonSuccessBaseSchema.and(
            z
              .strictObject({
                result: z.any().exactOptional(),
                msg: z.any().exactOptional(),
                ignored_parameters_unsupported: z.any().exactOptional(),
              })
              .openapi({ example: { msg: '', result: 'success' }, required: [] }),
          ),
        },
      },
    },
    400: {
      description: 'Bad request.',
      content: {
        'application/json': {
          schema: z.xor([
            InvitationFailedErrorSchema.and(
              z
                .any()
                .openapi({
                  example: {
                    result: 'error',
                    msg: "Some of those addresses are already using Zulip, so we didn't send them an invitation. We did send invitations to everyone else!",
                    errors: [['hamlet@zulip.com', 'Already has an account.', false]],
                    sent_invitations: true,
                    license_limit_reached: false,
                    daily_limit_reached: false,
                    code: 'INVITATION_FAILED',
                  },
                  description:
                    'An example JSON error response for when some of the specified email addresses\nhave existing Zulip accounts.\n',
                }),
            ),
            CodedErrorSchema.and(
              z
                .any()
                .openapi({
                  example: { code: 'BAD_REQUEST', msg: 'Insufficient permission', result: 'error' },
                  description:
                    "An example JSON error response for when the user doesn't have permission\nto send invitations.\n",
                }),
            ),
            CodedErrorSchema.and(
              z
                .any()
                .openapi({
                  example: {
                    code: 'BAD_REQUEST',
                    msg: 'You must specify at least one email address.',
                    result: 'error',
                  },
                  description:
                    'An example JSON error response for when no email address is specified.\n',
                }),
            ),
            CodedErrorSchema.and(
              z
                .any()
                .openapi({
                  example: {
                    code: 'BAD_REQUEST',
                    msg: 'Invalid channel ID 11. No invites were sent.',
                    result: 'error',
                  },
                  description:
                    'An example JSON error response for when any of the specified channels\ndoes not exist or the user does not have permission to access one of\nthe targeted channels.\n',
                }),
            ),
            CodedErrorSchema.and(
              z
                .any()
                .openapi({
                  example: {
                    code: 'BAD_REQUEST',
                    msg: 'You do not have permission to subscribe other users to channels.',
                    result: 'error',
                  },
                  description:
                    "An example JSON error response for when the user doesn't have permission\nto subscribe other users to channels and `stream_ids` is not empty.\n",
                }),
            ),
          ]),
        },
      },
    },
  },
})

