export const getStreamsRoute = createRoute({
  method: 'get',
  path: '/streams',
  tags: ['channels'],
  summary: 'Get all channels',
  description: 'Get all channels that the user [has access to](/help/channel-permissions).\n',
  operationId: 'get-streams',
  request: {
    query: z.object({
      include_public: z
        .stringbool()
        .default(true)
        .exactOptional()
        .openapi({
          param: {
            name: 'include_public',
            in: 'query',
            description: 'Include all public channels.\n',
            schema: { type: 'boolean', default: true },
            example: false,
            required: false,
          },
        }),
      include_web_public: z
        .stringbool()
        .default(false)
        .exactOptional()
        .openapi({
          param: {
            name: 'include_web_public',
            in: 'query',
            description: 'Include all web-public channels.\n',
            schema: { type: 'boolean', default: false },
            example: true,
            required: false,
          },
        }),
      include_subscribed: z
        .stringbool()
        .default(true)
        .exactOptional()
        .openapi({
          param: {
            name: 'include_subscribed',
            in: 'query',
            description: 'Include all channels that the user is subscribed to.\n',
            schema: { type: 'boolean', default: true },
            example: false,
            required: false,
          },
        }),
      exclude_archived: z
        .stringbool()
        .default(true)
        .exactOptional()
        .openapi({
          param: {
            name: 'exclude_archived',
            in: 'query',
            description:
              'Whether to exclude archived streams from the results.\n\n**Changes**: New in Zulip 10.0 (feature level 315).\n',
            schema: { type: 'boolean', default: true },
            example: true,
            required: false,
          },
        }),
      include_all_active: z
        .stringbool()
        .default(false)
        .exactOptional()
        .openapi({
          param: {
            name: 'include_all_active',
            in: 'query',
            description:
              'Deprecated parameter to include all channels. The user must\nhave administrative privileges to use this parameter.\n\n**Changes**: Deprecated in Zulip 10.0 (feature level\n356). Clients interacting with newer servers should use\nthe equivalent `include_all` parameter, which does not\nincorrectly hint that this parameter, and not\n`exclude_archived`, controls whether archived channels\nappear in the response.\n',
            schema: { type: 'boolean', default: false },
            deprecated: true,
            example: true,
            required: false,
          },
        }),
      include_all: z
        .stringbool()
        .default(false)
        .exactOptional()
        .openapi({
          param: {
            name: 'include_all',
            in: 'query',
            description:
              'Include all channels that the user has metadata access to.\n\nFor organization administrators, this will be all channels\nin the organization, since organization administrators\nimplicitly have metadata access to all channels.\n\n**Changes**: New in Zulip 10.0 (feature level 356). On older\nversions, use `include_all_active`, which this replaces.\n',
            schema: { type: 'boolean', default: false },
            example: true,
            required: false,
          },
        }),
      include_default: z
        .stringbool()
        .default(false)
        .exactOptional()
        .openapi({
          param: {
            name: 'include_default',
            in: 'query',
            description: "Include all default channels for the user's realm.\n",
            schema: { type: 'boolean', default: false },
            example: true,
            required: false,
          },
        }),
      include_owner_subscribed: z
        .stringbool()
        .default(false)
        .exactOptional()
        .openapi({
          param: {
            name: 'include_owner_subscribed',
            in: 'query',
            description:
              "If the user is a bot, include all channels that the bot's owner is\nsubscribed to.\n",
            schema: { type: 'boolean', default: false },
            example: true,
            required: false,
          },
        }),
      include_can_access_content: z
        .stringbool()
        .default(false)
        .exactOptional()
        .openapi({
          param: {
            name: 'include_can_access_content',
            in: 'query',
            description:
              'Include all the channels that the user has content access to.\n\n**Changes**: New in Zulip 10.0 (feature level 356).\n',
            schema: { type: 'boolean', default: false },
            example: true,
            required: false,
          },
        }),
    }),
  },
  responses: {
    200: {
      description: 'Success.',
      content: {
        'application/json': {
          schema: JsonSuccessBaseSchema.and(
            z
              .strictObject({
                result: z.any().exactOptional(),
                msg: z.any().exactOptional(),
                ignored_parameters_unsupported: z.any().exactOptional(),
                streams: z
                  .array(
                    BasicChannelBaseSchema.and(
                      z
                        .strictObject({
                          stream_id: z.any(),
                          name: z.any(),
                          is_archived: z.any(),
                          description: z.any(),
                          date_created: z.any(),
                          creator_id: z.any().nullable(),
                          invite_only: z.any(),
                          rendered_description: z.any(),
                          is_web_public: z.any(),
                          stream_post_policy: z.any(),
                          message_retention_days: z.any().nullable(),
                          default_push_notifications: z.any(),
                          history_public_to_subscribers: z.any(),
                          topics_policy: z.any().exactOptional(),
                          first_message_id: z.any().nullable(),
                          folder_id: z.any().nullable(),
                          is_recently_active: z.any(),
                          is_announcement_only: z.any(),
                          can_add_subscribers_group: z.any().exactOptional(),
                          can_remove_subscribers_group: z.any(),
                          can_administer_channel_group: z.any().exactOptional(),
                          can_delete_any_message_group: z.any().exactOptional(),
                          can_delete_own_message_group: z.any().exactOptional(),
                          can_move_messages_out_of_channel_group: z.any().exactOptional(),
                          can_move_messages_within_channel_group: z.any().exactOptional(),
                          can_send_message_group: z.any().exactOptional(),
                          can_resolve_topics_group: z.any().exactOptional(),
                          can_subscribe_group: z.any(),
                          can_create_topic_group: z.any().exactOptional(),
                          subscriber_count: z.any(),
                          stream_weekly_traffic: z
                            .int()
                            .nullable()
                            .openapi({
                              description:
                                'The average number of messages sent to the channel per week, as\nestimated based on recent weeks, rounded to the nearest integer.\n\nIf `null`, no information is provided on the average traffic.\nThis can be because the channel was recently created and there\nis insufficient data to make an estimate, or because the server\nwishes to omit this information for this client, this realm, or\nthis endpoint or type of event.\n\n**Changes**: New in Zulip 8.0 (feature level 199). Previously,\nthis statistic was available only in subscription objects.\n',
                            }),
                          is_default: z
                            .boolean()
                            .exactOptional()
                            .openapi({
                              description:
                                'Only present when [`include_default`][include_default]\nparameter is `true`.\n\nWhether the given channel is a\n[default channel](/help/set-default-channels-for-new-users).\n\n[include_default]: /api/get-streams#parameter-include_default\n',
                            }),
                        })
                        .openapi({
                          required: [
                            'stream_id',
                            'name',
                            'is_archived',
                            'description',
                            'date_created',
                            'creator_id',
                            'invite_only',
                            'rendered_description',
                            'is_web_public',
                            'stream_post_policy',
                            'message_retention_days',
                            'default_push_notifications',
                            'history_public_to_subscribers',
                            'first_message_id',
                            'folder_id',
                            'is_announcement_only',
                            'can_remove_subscribers_group',
                            'can_subscribe_group',
                            'stream_weekly_traffic',
                            'is_recently_active',
                            'subscriber_count',
                          ],
                        }),
                    ),
                  )
                  .exactOptional()
                  .openapi({
                    description:
                      'A list of channel objects with details on the requested channels.\n',
                  }),
              })
              .openapi({
                example: {
                  msg: '',
                  result: 'success',
                  streams: [
                    {
                      can_add_subscribers_group: 10,
                      can_remove_subscribers_group: 10,
                      can_subscribe_group: 10,
                      creator_id: null,
                      date_created: 1691057093,
                      description: 'A private channel',
                      first_message_id: 18,
                      folder_id: 1,
                      is_recently_active: true,
                      history_public_to_subscribers: false,
                      invite_only: true,
                      is_announcement_only: false,
                      is_archived: false,
                      is_default: false,
                      is_web_public: false,
                      message_retention_days: null,
                      default_push_notifications: false,
                      name: 'management',
                      rendered_description: '<p>A private channel</p>',
                      stream_id: 2,
                      stream_post_policy: 1,
                      stream_weekly_traffic: null,
                      subscriber_count: 20,
                    },
                    {
                      can_add_subscribers_group: 9,
                      can_remove_subscribers_group: 9,
                      can_subscribe_group: 10,
                      creator_id: 12,
                      date_created: 1691057093,
                      description: 'A default public channel',
                      first_message_id: 21,
                      folder_id: null,
                      is_recently_active: true,
                      history_public_to_subscribers: true,
                      invite_only: false,
                      is_announcement_only: false,
                      is_archived: false,
                      is_default: true,
                      is_web_public: false,
                      message_retention_days: null,
                      default_push_notifications: false,
                      name: 'welcome',
                      rendered_description: '<p>A default public channel</p>',
                      stream_id: 1,
                      stream_post_policy: 1,
                      stream_weekly_traffic: null,
                      subscriber_count: 10,
                    },
                  ],
                },
                required: [],
              }),
          ),
        },
      },
    },
  },
})

