export const getUserGroupsUserGroupIdMembersRoute = createRoute({
  method: 'get',
  path: '/user_groups/{user_group_id}/members',
  tags: ['users'],
  summary: 'Get user group members',
  description:
    'Get the members of a [user group](/help/user-groups).\n\n**Changes**: Prior to Zulip 12.0 (feature level 496), bot\nusers were not permitted to call this endpoint.\n\nNew in Zulip 6.0 (feature level 127).\n',
  operationId: 'get-user-group-members',
  request: {
    params: z.object({ user_group_id: UserGroupIdParamsSchema }),
    query: z.object({ direct_member_only: DirectMemberOnlyParamsSchema }),
  },
  responses: {
    200: {
      description: 'Success',
      content: {
        'application/json': {
          schema: JsonSuccessBaseSchema.and(
            z
              .strictObject({
                result: z.any().exactOptional(),
                msg: z.any().exactOptional(),
                ignored_parameters_unsupported: z.any().exactOptional(),
                members: z
                  .array(z.int())
                  .exactOptional()
                  .openapi({
                    description: 'A list containing the user IDs of members of the user group.\n',
                  }),
              })
              .openapi({
                example: { msg: '', result: 'success', members: [10, 12] },
                required: [],
              }),
          ),
        },
      },
    },
  },
})

